pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small post_residual gaps are hard to fill later.
    if post_residual > 0 {
        // Ratio of leftover space; small gaps (< ~15) are "dead".
        let dead_zone = 15.0;
        if (post_residual as f64) < dead_zone {
            // Penalize heavily: the smaller the gap relative to dead zone, the worse.
            score += (dead_zone - post_residual as f64) * 12.0;
        }
        // Reward usable gaps that can still host future items (>= typical small item).
        if post_residual >= 10 {
            score -= 8.0;
        } else {
            score += 20.0; // gap below 10 is essentially unusable
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 30.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin (avoid bin proliferation).
        score += 40.0;
        // If many open bins already exist with poor mean residual, opening fresh is fine.
        if open_bins_count > 0 && mean_residual < 25.0 {
            score -= 45.0;
        }
        // If next item is large and current bins are tight, new bin helps.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 25.0;
        }
    } else {
        // Prefer reusing existing bins, but with open_bins_count pressure:
        // more open bins -> push toward consolidating into bins with larger residual usage.
        score += (open_bins_count as f64) * 0.5;
        // Reward bins whose residual is close to mean residual (balanced packing).
        score -= 1.0 / (1.0 + ((bin_residual as f64) - mean_residual).abs());
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 10.0;
    }

    // Stream progression: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // dead space that even the next item can't use
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: with many open bins, prefer filling
    // existing bins over spreading; with few bins, opening new is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * (2.0 + 4.0 * progress);

    // New-bin candidate: baseline slightly below mean residual so it is only
    // chosen when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = mean_residual * 0.45 + 14.0 + bin_pressure * 1.5 - 20.0 * progress;
        if fitting_bins_count <= 1 {
            score += 30.0; // never open new bin if only one fits
        }
    } else {
        // Mild preference for bins tighter than the average residual.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

