    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to bin capacity.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: more open bins -> prefer packing into existing bins.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: only attractive when the fit is very tight or no good existing option.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity as f64;
        score += 15.0;
        score -= 50.0 * tight;
        if post_residual > 0 && post_residual < 10 {
            score += 30.0; // opening a fresh bin to create dead space is bad
        }
    }

    // Lookahead: if next item would fit the post residual, bonus for this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += 3.0 * (mean_residual - bin_residual as f64);

    // Early stream: slightly more willing to open bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for typical items) is heavily penalized, scaled by how dead it is.
    if post_residual > 0 {
        let dead_threshold = 10.0 + 0.35 * item_size as f64;
        if (post_residual as f64) < dead_threshold {
            let deadness = 1.0 - (post_residual as f64) / dead_threshold;
            score += 60.0 * deadness * deadness;
        } else {
            score -= 5.0; // roomy leftover: mild reward
        }
    } else {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Reward bins whose leftover can still host the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 10.0; // leftover likely wasted for next item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmentation;
    // with few open bins, tolerate spreading to keep options open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when the item would leave
    // a large, useful gap here or fits poorly among all open bins.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 45.0 - 25.0 * tightness;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin serves the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 60.0; // no real alternative: open the new bin
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0; // existing bins are mostly too full
        }
    }

    // Late in the stream, prefer closing bins out (waste less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= 50 {
        score -= 15.0;
    } else if post_residual < 30 {
        // Mid-range dead zone: mildly penalize unusable-ish gaps.
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item won't fit here -> residual becomes dead space
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> consolidate into existing ones.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins) to keep large residuals available for large items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin is attractive only when
    // existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; opening is preferred over wasting space
        // in near-full bins, but discouraged when a good fit exists.
        score = 45.0 + item_size as f64 * 0.2;
        if post_residual == 0 { score -= 60.0; } // unreachable, keep safe
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post > 0.0 {
        let next = next_item_size as f64;
        // If the leftover gap cannot fit the next item, it is likely dead space.
        if next > 0.0 && post < next {
            score += 25.0 * (1.0 - post / next);
        }
        // Absolute tiny-gap penalty (unusable slivers).
        if post < 10.0 {
            score += 40.0;
        } else if post < 20.0 {
            score += 15.0;
        }
    } else {
        // Perfect fill is strongly rewarded.
        score -= 50.0;
    }

    // Reward fits that leave room for the lookahead item exactly.
    let next = next_item_size as f64;
    if next > 0.0 && (post - next).abs() < f64::EPSILON {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly,
    // but reward using the last-chance bin.
    score += 0.8 * open_bins_count as f64;
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    score -= 10.0 * (item_size as f64 / bin_residual as f64);

    // Slight preference to keep mean residual high (balanced bins).
    score += 0.05 * (mean_residual - post).abs();

    // New-bin candidate: only open a new bin when all open fits are bad.
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin; discounted late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 - 10.0 * progress;
        // If the item is large and no good fit exists, opening is cheaper.
        if item_size > 50 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (1..=9) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Tight-but-usable fit: reward small usable residuals.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 12.0;
    }
    // Large leftover space: mild penalty to avoid squandering big gaps on small items.
    if post_residual > 50 {
        score += 0.5 * (post_residual as f64 - 50.0);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 8.0 + 10.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score -= new_bin_bonus.max(-20.0);
    } else {
        score += 2.0 * open_bins_count as f64 / (1.0 + progress);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size + 10 {
            score -= 5.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // creates unusable gap for the known next item
        }
    }

    // Prefer bins below mean residual (saves tighter bins for tighter fits).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let tight = (fit_ratio - 0.5) * (fit_ratio - 0.5); // penalize half-empty tails quadratically
    let tight4 = tight * tight;
    score += 40.0 * tight4 * (0.5 + progress) * cap;

    // Reward near-perfect fits with progress-scaled bonus
    let perfect = 1.0 - fit_ratio;
    score -= 25.0 * perfect * perfect * perfect * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item fits poorly in resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score += 0.15 * gap;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).sqrt() * 0.5;
    // Mean-residual coupling: prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: keep neutral baseline, slightly favored late when residuals are small
    if bin_residual == bin_capacity {
        score = pr - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: quadratic/cubic shaping of post-residual scaled by progress
    score += (norm_pr * norm_pr) * (20.0 + 40.0 * progress);
    score -= (norm_pr * norm_pr * norm_pr) * 30.0 * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize small dead space that becomes unusable (smooth hinge-like polynomial)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 10.0 {
