    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Deviation from mean residual: prefer bins near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: make empty bins less attractive unless residual is poor
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress;
    }

    score
}

