    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to wasted space.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Compare against mean residual: prefer bins tighter than average (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make opening a new bin costly unless it enables a great 2-step chain.
    if bin_residual == bin_capacity {
        let mut newbin = 250.0;
        if next_item_size > 0 {
            let residual_after_next = bin_capacity.saturating_sub(item_size).saturating_sub(next_item_size);
            if residual_after_next == 0 {
