            } else if residual_after_next <= 10 {
                newbin = -200.0;
            }
        }
        score = newbin + 0.1 * item_size as f64;
    }

    // Mild late-stream tightening: as stream progresses, avoid leaving many sloppy gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // (<= 10) are almost certainly wasted, so punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
