        score -= 100.0;
    }

    // If the next item fits exactly into the post-residual, this placement is
    // doubly valuable (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // If the next item cannot fit in the post-residual and the gap is small,
    // this bin is likely to become dead space for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 25.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty so tighter-fitting alternatives win among many options.
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Open-bin pressure: with many open bins, avoid spreading across bins;
    // with few open bins, filling existing bins is cheap and good.
    let obp = open_bins_count as f64;
    score += (obp - 1.0) * 2.5;

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it becomes a "garbage" bin; slight penalty to prefer leaving compact bins.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 && post_f > mean_residual * 1.4 {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit (large item, or all open fits are poor). Give it a
    // baseline penalty so it loses to good fits, but it keeps its natural
    // post_residual (= capacity - item_size) advantage for large items.
    if bin_residual == bin_capacity {
        score += 35.0;
        // For very large items, opening fresh is often better than fragmenting.
        if item_size > 70 {
            score -= 40.0;
        }
    }

    // Slight stream-progression modulation: late in the stream, be more
    // conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

