        // Base cost of opening a new bin, softened when many bins already open
        // and mean residual is low (existing bins nearly full).
        let mut new_bin_cost = 150.0 + open_bins_count as f64 * 5.0;
        if mean_residual < 15.0 {
            new_bin_cost -= 80.0;
        }
        // If next item is large and this bin would be left with a tiny gap,
        // opening fresh is safer.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            new_bin_cost -= 100.0;
        }
        score += new_bin_cost;
    } else {
        // Reward placing into bins whose residual is close to the item size (tight packing).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score -= (bin_capacity as f64 - tightness) * 0.1;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 250.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // This placement creates a gap the next item cannot use.
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight superlinear penalty
    // for leaving awkward mid-range dead space.
    let pr = post_residual as f64;
    score += 0.15 * (pr / 10.0).powi(2) * (pr > 0.0) as i32 as f64;

    // 2-step lookahead: strongly reward residuals that exactly match the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (pr - next).abs();
        if diff == 0.0 {
            score -= 200.0; // perfect chaining: next item fills this bin exactly
        } else if next <= pr {
            // next item still fits here: reward proportionally to how snugly
            score -= 1.5 * (next / (diff + 1.0));
        } else {
            // next item cannot fit in the leftover: mild penalty scaled by gap
            score += 0.5 * (diff / next);
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual is good (bin nearly consumed), leaving more than average wastes space.
    score += 0.8 * (pr - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent open bins exist; the new-bin candidate
    // (bin_residual == bin_capacity) should only win if fits elsewhere are awful.
    if bin_residual == bin_capacity {
        score += 60.0;
        // A new bin is more attractive early in the stream (room to grow the pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // If next item is large, a fresh bin gives flexibility
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 25.0;
        }
    } else {
        // Slight penalty proportional to how many bins are already open
        // (encourage consolidation into fewer bins).
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins that become nearly full after placement.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Penalize small dead space (< 10) that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: reward if next item can fit the post residual (chaining).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            score += 12.0; // dead space relative to the known next item
        }
        // Bonus for leaving exactly room for next item (perfect chain).
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        }
    }

    // Relative deviation from mean residual: prefer bins tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Time horizon: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * tightness;

    // When many bins are open, discourage opening new ones; the new-bin
    // candidate has high post_residual so it scores worse naturally, but
    // add a mild consolidation pressure scaled by open bin count.
    score += 0.15 * (post_residual as f64) * (open_bins_count as f64).ln().max(0.0) * 0.05;

    // Early stream: be lenient about spreading items (keep flexibility).
    score -= 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual).
    let mut score = post;

    // Non-linear polynomial coupling: tightness reward grows with stream progress,
    // scaled by a smooth quartic in normalized post_residual.
    let tightness = (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + norm_post * norm_post);
    score -= 30.0 * progress * tightness;

    // Smooth penalty on residual that is too small to be reusable later:
    // dead-space term rises as post_residual falls below the smallest plausible item,
    // modeled with a smooth polynomial in norm_post.
    let dead = (0.20 - norm_post).max(0.0) / 0.20;
    score += 25.0 * dead * dead * (1.0 + 0.5 * progress);

    // Lookahead coupling: reward if next item fits smoothly into the post residual
    // (quadratic agreement term), penalize if next item barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - ((post - nxt) / cap).abs();
            score -= 12.0 * fit_quality * fit_quality * (1.0 - progress * 0.5);
        } else {
            let miss = ((nxt - post) / cap).min(1.0);
            score += 15.0 * miss * miss;
        }
    }

    // Last-chance bonus: smooth inverse coupling with fitting_bins_count.
    if fitting_bins_count <= 1 {
        score -= 20.0 + 10.0 * progress;
    } else {
        score -= 8.0 / (fitting_bins_count as f64).powf(1.5);
    }

    // Mild dispersion penalty: avoid bins far from the mean residual (smooth quadratic).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin, more so early and when
    // open bins exist; smooth in progress and open_bins_count.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let open_factor = 1.0 / (1.0 + (open_bins_count as f64).ln().max(1.0));
        score += 18.0 * (1.0 - 0.6 * progress) * open_factor;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into coarse buckets
    // via integer division on capacity fractions (e.g. quarters of capacity).
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 harmonic class
    let class_penalty = match class {
        0 => -8.0,          // post_residual < C/4 : tiny dead space, excellent
        1 => -2.0,          // C/4..C/2 : still useful
        2 => 1.5,           // C/2..3C/4 : mediocre
        3 => 4.0,           // 3C/4..C : large hole forming
        _ => 0.0,           // empty-bin candidate
    };
    score += class_penalty;

    // Modulo coupling: reward when post_residual aligns with the small-item
    // granularity (items >= 1, so multiples of 5 are common landing zones).
    let mod_bonus = (post_residual % 5) as f64;
    score -= 0.8 * (4.0 - mod_bonus) / 4.0;

    // Perfect-fit harmonic reward: post_residual zero is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead harmonic class: can next_item_size land exactly in the hole
    // (post_residual % next_item_size == 0) or at least fit?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual % next_item_size == 0 {
                score -= 10.0; // perfect chained fit
            } else {
                score -= 3.0;
            }
        } else {
            // next item cannot use this hole: penalize proportionally to waste
            score += 2.0 * (next_item_size as f64 / cap_f) * 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Empty-bin candidate handling: only attractive when residuals across open
    // bins are large (mean_residual high) meaning existing bins are roomy anyway.
    if bin_residual == bin_capacity {
        score += 4.0 * (mean_residual / cap_f);
        // early in stream, opening fresh bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 * (1.0 - progress);
        // discourage new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 && post_residual + item_size <= bin_capacity {
            score += 2.0;
        }
    }

    // Tightness coupling: prefer bins where the item fills a large fraction
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fill.min(1.0);

    // Crowding: many open bins -> consolidate into existing ones
    score += 0.15 * open_bins_count as f64 * (mean_residual / cap_f).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect or near-perfect fills are highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A gap is "dead" if no plausible future item can use it (items >= 1 here,
    // so treat very small gaps relative to typical item sizes as dead).
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 45.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Penalize gaps that can't even fit the lookahead item (likely dead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Last chance: if this is the only bin that fits, prefer using it over
    // opening a new bin (unless the fit would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheap so favor tight fits elsewhere.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin is a fresh start; make it
    // attractive only when the current fit is poor, otherwise discourage.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 60 {
            score -= 20.0; // big items are fine to start a fresh bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // room for lookahead pairing
        }
    }

    // Mild bonus for filling bins far above mean residual (consolidation).
    if (bin_residual as f64) > mean_residual + 1.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that nothing can use
        if post_residual < 10 {
            score += 200.0;
        }
    }

    // 2-step lookahead: reward if next item fits exactly in the post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.5 * chain_fit;
        if chain_fit == 0.0 {
            score -= 300.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item won't fit here; penalize creating near-dead residual
        let waste = post_residual as f64;
        score += 0.3 * waste;
        // If next item is small enough to fit in other bins, dead space is worse
        if next_item_size < bin_residual {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare residual against mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 5.0 * (rel - 1.0);
    }

    // Early in stream: be conservative, prefer tight fits less aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    // New empty bin candidate: penalize slightly so it's only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if no open bin fits well, allow new bin
        if next_item_size > 0 && item_size as f64 > mean_residual {
            score -= 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals nonlinearly (dead space that is hard to fill).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 0.35 * (pr * pr) / bin_capacity as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit bonus: small post-residual relative to item size.
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score -= 12.0 / (1.0 + tightness);

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.05 * waste;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover too small for next item: penalize proportionally to progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 8.0 * progress;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    score += 0.6 * open_bins_count as f64;

    // Global residual dispersion: if this bin's residual is above mean, it's roomier;
    // filling roomy bins first preserves tight bins for tight items.
    let resid = bin_residual as f64;
    if resid > mean_residual {
        score -= 0.15 * (resid - mean_residual);
    } else {
        score += 0.2 * (mean_residual - resid);
    }

    // New-bin candidate: discourage unless item is large relative to capacity or
    // no open bin is a good fit (post_residual in an existing bin would be big).
    if bin_residual == bin_capacity {
        let rel = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: opening bins is cheap; late stream: fill existing bins.
        score += 30.0 - 25.0 * rel - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth non-linear coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.6 * progress * norm_post) + 8.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly late in the stream.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress;

    // Penalize dead space relative to mean residual across open bins.
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty on opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by small
    // integers are more reusable (e.g., 0, 25, 50, 75, 100 style classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "clean" fractions of capacity (usable classes).
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual <= tenth {
        score -= 12.0; // near-perfect, negligible dead space
    } else if post_residual % quarter == 0 {
        score -= 10.0; // harmonic quarter-class residual
    } else if post_residual % fifth == 0 {
        score -= 6.0; // harmonic fifth-class residual
    } else if post_residual >= quarter {
        score += 4.0; // large awkward leftover
    }

    // Penalize residuals that no plausible future item can fill well.
    // Items are 1..=100; a residual r is "fillable" if next item or small
    // future items (>= ~10) can use it. Dead zone: 1..=9 unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item fits at all, mild reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Harmonic divisibility between leftover and next item.
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover: slight penalty,
            // scaled by how much it overshoots.
            score += (nx - pr) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the current residual (high fill ratio = good packing).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Mild pressure to consolidate: with many open bins, favor placing
    // into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins below mean residual (denser bins) early; as stream
    // progresses, allow more freedom.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr - mean_residual) * (0.1 - 0.05 * progress);

    // New-bin candidate: opening a fresh bin is only good if the current
    // item is large relative to capacity (it deserves its own space) or
    // no existing bin fits well.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score -= 10.0; // big item: fresh bin is fine
        } else {
            score += 35.0 + (cap - item_size as f64) * 0.2; // discourage wasting a new bin on small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..~10)
    // are worthless -> hard penalty proportional to their uselessness.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: penalize heavily, scaled by how much of the
            // residual it wastes relative to capacity.
            score += 25.0 * (10.0 - post_residual as f64) / 10.0;
        } else if post_residual < 20 {
            // Marginal zone: only next-item-sized gaps are salvageable.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 8.0; // lookahead fits: good dead space
            } else {
                score += 10.0 * (1.0 - post_residual as f64 / 20.0);
            }
        }
    } else {
        // Perfect closure: best possible outcome.
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual already low, add coupling).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Lookahead synergy: if the next item exactly matches post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer
    // filling existing bins and only open new ones under last-chance pressure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.8 * pressure;

    // Last-chance bin: if this is the only fitting bin, opening a new bin
    // would strand this residual forever -> strong reward for using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a
    // good fit (i.e., when this bin's residual would leave a bad gap).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, offset when current item is large
        // (large items in fresh bins leave more usable residual later).
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 18.0;
        score = 30.0 - large_item_bonus;
        // Late in the stream, opening new bins is cheaper than stranding gaps.
        score -= 10.0 * progress;
        // If many bins are open, discourage adding another unless necessary.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild tie-break: prefer bins with residual near the mean (balanced load),
    // avoiding extreme outliers that create fragmented small gaps.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but weight by how "wasted" the space is
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: strongly reward exact match or near-exact match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: next item exactly fills this bin afterwards
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how close next item comes to filling remainder
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; remainder becomes dead space until something smaller arrives
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (gap / 100.0);
        }
    } else {
        // Last item: only post_residual matters
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual below the mean (consolidate small leftovers),
    // avoid emptying large-residual bins into more fragmentation
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild penalty for opening a new bin when open bins exist and stream is early/mid
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual) with a non-linear penalty
    let post = post_residual as f64;
    score += 0.35 * (post / bin_capacity as f64) * (post / bin_capacity as f64) * (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        // Extra reward for exact chain fit
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the known next item: penalize proportionally to wasted space
        score += 0.10 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global pressure: when many open bins, prefer filling existing ones over opening new
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are already open bins
        // and mean residual is large enough to absorb items
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 0.25 * open_bins_count as f64 + 10.0 * mean_residual / bin_capacity as f64;
        // Late in the stream, opening new bins is even less desirable
        score += 6.0 * progress;
        // But if item is large, new bin becomes relatively more attractive
        score -= 0.05 * item_size as f64;
    } else {
        // Fitting an open bin: small reward scaled by how full it already is
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 4.0 * fill;
        // Prefer bins whose residual is below the mean (compact small bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Mild preference for placing large items into large-residual bins
    score -= 0.03 * (item_size as f64) * (bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 30.0 * pr_norm * pr_norm;

    // Smooth stream-progress coupling: later in the stream, waste is penalized more sharply
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Dead-space penalty: post-residual that is too small to fit a typical future item
    let dead = (1.0 - (pr / 40.0).min(1.0)).abs() - 1.0; // 0 when pr>=40, -1 when pr=0
    score += 15.0 * dead * (0.5 + progress);

    // Lookahead: reward bins whose post-residual fits the next item (smoothly)
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64).max(0.0);
        let slack = (next_item_size as f64 - pr).max(0.0);
        score -= 10.0 * (1.0 - fits_next / cap) * (1.0 - progress);
        score += 5.0 * slack / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight preference for bins tighter than the mean (good packing)
    score -= 3.0 * (mean_residual - bin_residual as f64) / cap;

    // Mild penalty for proliferating open bins early in the stream
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands. Small leftovers (tight fits) are excellent,
    // mid-range leftovers (dead space) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Dead-space band: leftover between 25% and 50% of capacity is the
    // hardest to fill later (items are 1..=100 and mid sizes are common).
    if frac > 0.25 && frac < 0.5 {
        score += 12.0 * (0.5 - frac);
    }

    // Perfect/near-perfect fit: leftover < 10% is a gem, reward strongly.
    if post_residual <= bin_capacity / 10 {
        score -= 15.0;
    }

    // Harmonic residue classes via integer division on post_residual:
    // leftovers that are multiples of 10 align with typical item sizes.
    let cls = post_residual / 10;
    if cls == 0 {
        score -= 20.0; // exact fit
    } else if cls <= 2 {
        score -= 8.0;  // small usable gap
    } else if cls >= 5 && cls <= 7 {
        score += 6.0;  // awkward gap zone
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            if npost <= bin_capacity / 10 {
                score -= 12.0; // chain leads to near-exact fit
            }
            // Penalize if next item leaves another awkward mid gap
            let nfrac = npost as f64 / cap;
            if nfrac > 0.25 && nfrac < 0.5 {
                score += 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover; the gap becomes
            // permanent dead space for at least one step.
            score += frac * 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + item_size as f64 * 0.05;
    }

    // New-bin candidate (empty bin): only attractive when the item is
    // large or no open bin offers a decent fit. Base it on residual
    // structure so an empty bin loses to any reasonable fit.
    if bin_residual == bin_capacity {
        // Empty bin score: penalize when open bins exist and mean
        // residual is healthy (we should use existing space).
        if open_bins_count > 0 {
            score += 8.0 + mean_residual * 0.15;
        }
        // But large items start fresh bins happily (keeps big items
        // paired with big leftovers for later big items).
        if item_size >= bin_capacity * 3 / 5 {
            score -= 6.0;
        }
    }

    // Stream progression: early in the stream, be more willing to open
    // bins / keep flexibility; late in the stream, squeeze tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0; // late stream: favor tightest fits slightly more

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    let dead_zone = 25.0; // gaps below this are likely unusable for future items
    if pr > 0.0 && pr < dead_zone {
        // quadratic penalty growing as the gap shrinks toward zero
        score += (dead_zone - pr) * (dead_zone - pr) / 12.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item cannot fit in post_residual (dead end for the chain)
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild preference toward bins tighter than the mean (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        let would_be_dead = pr > 0.0 && pr < dead_zone;
        if would_be_dead {
            score -= 45.0; // prefer fresh bin over creating dead space
        } else {
            score += 35.0; // keep using open bins when fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space relative to mean residual (wasted capacity).
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.6 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect 2-step match: post residual exactly fits next item.
        if post_residual as f64 == nxt {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: reward tight coupling.
            score -= 8.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize small leftover dead space.
            score += 5.0 * (1.0 - pr / bin_capacity as f64);
        }
        // Bonus if next item also fits tightly after this placement.
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Brand-new bin candidate: only attractive when item is large relative to capacity
    // or current open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 12.0 * fill - 4.0 * crowding.min(3.0);
        // Discourage opening new bins when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual as f64 <= mean_residual {
            score += 15.0;
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post residual can hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Exact pairing bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding pressure: with many open bins, prefer filling existing ones.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 3.0 * crowding;

    // Time horizon: later in the stream, be more conservative (prefer tight fits,
    // avoid spreading across bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // New-bin candidate: make opening a new bin costly unless item is large
    // relative to residuals available or the bin is empty and item is huge.
    if bin_residual == bin_capacity {
        // Empty-bin baseline: penalize so it is only chosen when it beats others.
        score += 35.0 + 0.3 * item_size as f64;
        // Late stream: opening fresh bins is less wasteful early, costly late.
        score += 20.0 * progress;
        // If the item is very large, a fresh bin may be the best home.
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to the item (minimal waste metric).
    let waste_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * waste_gap;

    // Mean residual coupling: if average residual is high, we have slack everywhere;
    // slightly reward using any bin; if low, be pickier about exact fits.
    if mean_residual < 15.0 {
        score += 5.0 * (1.0 - fit_ratio);
    } else {
        score -= 2.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with a convexity that grows over the stream.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Smooth polynomial coupling: residual squared term weighted by progress
    score += 0.35 * norm_pr * norm_pr * (1.0 + progress) * cap;

    // Reward tight fits via smooth saturating term on post_residual
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Dead-space penalty: residuals too small for typical future items
    let dead = if pr > 0.0 { ((20.0 - pr) / 20.0).max(0.0) } else { 0.0 };
    score += 15.0 * dead * dead;

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: penalize if post_residual can't fit next item, smoothly
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score += (1.0 - fits_next) * (4.0 + 6.0 * progress);
        score -= fits_next * 3.0 * (1.0 - (pr / (next_item_size as f64 + pr)).powi(2));
    }

    // Mild dispersion penalty: bins far from mean residual are less attractive
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate handling: smooth preference scaling with progress
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residue modulo capacity fractions ---
    // Dead-space classes: post_residual in {0} is perfect; small residues (1..10)
    // are nearly useless; residues that are harmonic divisors of 100 (10,20,25,50)
    // remain reusable for common item sizes.
    let perfect_fit = if post_residual == 0 { -400.0 } else { 0.0 };
    score += perfect_fit;

    // Harmonic divisor bonus: post_residual that divides capacity evenly
    // (10, 20, 25, 50) is a "usable class" — reward it.
    if post_residual > 0 && (bin_capacity % post_residual) == 0 {
        score -= 30.0;
    }

    // Non-harmonic small residue penalty (dead space class 1..=9)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // --- Modulo class coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead fits here: strong reward, scaled by snugness
            let snug = (post_residual - next_item_size) as f64;
            score -= 55.0 - 0.4 * snug;
        } else {
            // Lookahead blocked: penalize if post_residual is a "teasing" residue
            // that almost fits the next item (within one harmonic class of 10)
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 35.0;
            }
        }
    }

    // --- Integer-division threshold on post_residual vs item_size ---
    // Favor bins where the item consumes a large integer fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // --- Last-chance bin: if this is the only fitting bin, avoid wasting it
    // on a small item when post_residual would still be large ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64;
        if waste > 50.0 {
            score += 0.5 * (waste - 50.0);
        } else {
            score -= 20.0; // good snug use of scarce bin
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Prefer opening a new bin late in the stream or when open bins are
        // fragmented (mean residual low relative to next item).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if next_item_size > 0 {
            (mean_residual - next_item_size as f64).max(0.0)
        } else {
            mean_residual
        };
        // Open new bin when existing bins are poor hosts (high post_residual here)
        score -= 25.0 + 30.0 * progress + 0.3 * fragmentation;
        // But discourage new bins when many bins already open and mean residual is high
        score += 0.15 * open_bins_count as f64 + 0.2 * mean_residual.max(0.0);
    }

    // --- Modulo-10 harmonic class of post_residual: residues matching common
    // item-size grid (multiples of 10) stay compatible with future arrivals ---
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (< 1) are worthless; here anything below ~10 is a gap
    // only usable if a future tiny item appears. Penalize hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 8.0 * fill_ratio;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement; if post residual can't fit the
    // next item but another gap could, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer the one wasting less.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than spreading; discourage new bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * open_pressure;

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and this bin would be well-filled by the item.
        let new_fill = item_size as f64 / bin_capacity as f64;
        let crowded = mean_residual < (bin_capacity as f64) * 0.35;
        if crowded && new_fill > 0.5 {
            score -= 5.0 * new_fill;
        } else {
            score += 15.0 + 10.0 * (1.0 - new_fill);
        }
    }

    // Early in the stream, slightly favor opening bins to build a diverse
    // residual pool; late in the stream, favor tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual small relative to capacity)
    let tight_fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight_fit * tight_fit * tight_fit;

    // 2-step lookahead: bonus if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chain: bin fully closed after two items
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / (bin_capacity as f64));
        } else {
            // next item cannot follow into this bin -> dead space penalty
            let dead = (next_item_size - post_residual) as f64;
            score += 8.0 + dead * 0.5;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end near the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize leaving large unusable gaps (post_residual < typical min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we prefer
    // using open bins unless the fit is very poor elsewhere
    if bin_residual == bin_capacity {
        score += 20.0;
        // early in stream, opening bins is cheaper (fewer bins to manage later)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference for fuller bins overall
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, but dead space
    // below the minimum item size (1..100 unknown, assume ~10) is wasted.
    let tiny = post_residual as f64;
    if tiny > 0.0 && tiny < 10.0 {
        score += 25.0 * (10.0 - tiny); // unusable sliver penalty
    } else {
        score -= 4.0 * (1.0 - tiny / bin_capacity as f64); // prefer fuller fills
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 3.0 * ((next_item_size as f64 - post_residual as f64) / 10.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be selective (penalize loose fits more);
    // late in stream, just close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Global state: many open bins with high mean residual -> encourage
    // consolidation into existing bins rather than opening new ones.
    if mean_residual > 0.0 {
        score += 0.15 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: minimize post residual, softly
    let mut score = pr_norm;

    // Smooth quadratic dead-space penalty growing with stream progress
    score += progress * pr_norm * pr_norm * 1.5;

    // Cubic interaction: large residuals late in stream are costly
    score += progress * progress * pr_norm.powi(3) * 2.0;

    // Reward tight fits: subtract when post_residual is small
    score -= (1.0 - pr_norm).powi(2) * 0.8;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // New-bin candidate: penalize mildly, more so early when open bins exist
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 0.6 + 0.25 * openness * (1.0 - progress);
        // but if next item is large and this bin stays empty anyway, slight relief
        let nxt = next_item_size as f64 / cap;
        score -= nxt * nxt * 0.3;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) == pr {
        score -= 1.0;
    }
    // If next item nearly fits, small reward for leaving that gap
    if next_item_size > 0 && (next_item_size as f64) < pr {
        score -= 0.3 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mean-residual coupling: prefer bins deviating below mean (tighter bins)
    let dev = (mean_residual - pr) / cap;
    score += 0.2 * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets create discrete
    // "goodness" tiers for leftover space.
    let post = post_residual as f64;
    let class = (post_residual % 10) as f64;
    // Residuals that are exact multiples of 10 are "harmonic" — they pair
    // cleanly with future items; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += class * 0.35; // penalize awkward fractional remainders
    }

    // Dead-space penalty: very small leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Integer-division threshold on post_residual: leftovers that could host
    // a minimum-size item (>=10) are valuable.
    if post_residual >= 10 {
        score -= (post_residual / 10) as f64 * 1.5;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this is a perfect chaining placement — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // harmonic tier of the gap after the hypothetical next placement
            if gap % 10 == 0 {
                score -= 10.0;
            }
            score += gap as f64 * 0.25;
        } else {
            // next item won't fit here: slight penalty scaled by overflow
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate handling: a fresh bin is attractive early in the
    // stream or when open bins are crowded, but we bias it so that existing
    // decent fits (post_residual <= ~35 with harmonic class) win instead.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // base cost of opening a new bin, decaying with progress
        score = 45.0 + 55.0 * (1.0 - progress) + crowding * 2.0;
        // a new bin is great if the current item is large (harmonic half/full)
        if item_size % 50 == 0 || item_size >= 60 {
            score -= 12.0;
        }
        // if next item is huge, having a fresh bin helps
        if next_item_size >= 60 {
            score -= 8.0;
        }
        return score;
    }

    // Mild pressure toward tighter bins when many are open.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0;
        if (slack as f64) < dead_zone {
            score += (dead_zone - slack as f64) * 4.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's remainder: mild penalty proportional to gap.
        score += ((next_item_size - post_residual) as f64).min(20.0) * 0.3;
    }

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count <= 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 25.0;
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: only allow opening a new bin when the current
    // item would leave a very poor fit in every existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin.
        score += 20.0;
        // If the item nearly fills the empty bin, opening is attractive.
        if (item_size as f64) > 0.85 * bin_capacity as f64 {
            score -= 40.0;
        }
        // If existing bins are fragmented (low mean residual), a new bin is fine.
        if mean_residual < 25.0 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter bins overall.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Perfect closure: bin exactly filled, never touched again ---
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            if gap < 0.5 {
                // Perfect 2-chain: next item exactly fills this bin afterwards.
                score -= 35.0;
            } else {
                // Next item still fits here; reward, scaled by how much
                // slack remains for items after that.
                score -= 6.0 + 0.08 * nxt - 0.05 * gap.min(40.0);
            }
        } else if pr > 0.0 {
            // Lookahead mismatch: leftover dead space the next item cannot use.
            // Penalize proportionally to the unusable gap.
            score += 0.5 * (nxt - pr).min(50.0);
        }
    }

    // --- Relative-to-mean coupling: prefer tighter-than-average bins,
    //     preserving roomy bins for larger future items. ---
    let excess = bin_residual as f64 - mean_residual;
    if excess > 0.0 {
        score += 0.15 * excess;
    }

    // --- Last-chance bonus: if this is the ONLY open bin that fits,
    //     strongly favor using it over opening a new bin. ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Mild standing penalty: an existing tight fit should usually win.
        score += 6.0;
        // But if the new bin enables a perfect chain or exact closure,
        // override the penalty aggressively.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
        if post_residual == 0 {
            score -= 45.0;
        }
        // Late in the stream, be more willing to open fresh bins
        // (remaining opportunity to consolidate is shrinking).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * progress;
    }

    // --- Stream progression: as the stream advances, closing bins cleanly
    //     becomes more valuable (fewer chances left to fill them). ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 2.0 * progress; // tiny dead space late in stream is worse
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Core best-fit term with a quadratic dead-space penalty.
    let mut score = post + 0.35 * post * post / cap;

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is generally worse than reusing; penalize,
        // scaled by how many alternatives exist. Relax slightly for big items.
        score += 12.0 + 2.0 * (fitting_bins_count as f64).min(6.0);
        if item >= 60.0 {
            score -= 10.0;
        }
    } else {
        // Last-chance bin: strongly reward using it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Lookahead: reward if the next item fits exactly or nearly in leftover.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= post {
                score -= 8.0;
            } else if nxt <= post + 10.0 {
                score -= 3.0;
            }
        }
        // Mild penalty if this bin's post-residual deviates from the global mean
        // (avoid creating outliers that fragment the bin set).
        score += 0.05 * (mean_residual - post).abs();
    }

    // Time-horizon coupling: late in the stream, consolidation matters more.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let open_f = open_bins_count as f64;
    score += t * 1.0 * open_f.max(1.0).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual weighted by progress-dependent polynomial
    let coupling = 1.0 + 2.0 * progress * progress - 1.5 * progress;
    score += 0.35 * (pr / cap) * (pr / cap) * cap * coupling;

    // Penalize small dead space quadratically (unusable slivers)
    if pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.5;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 8.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 4.0 * (ns - pr) / cap;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild reward for closing the gap between bin residual and mean residual (balance)
    score -= 0.1 * (mean_residual - pr).abs() / cap;

    // Penalize opening new bins when many bins already open early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Class by quarters of capacity — small leftovers are dead space.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = match post_residual {
        0 => 0u32,                      // perfect fit, best possible
        p if p < 10 => 1,               // nearly dead space
        p if p < quarter => 2,          // awkward sliver
        p if p < half => 3,             // usable small class
        p if p < 3 * quarter => 4,      // comfortable medium class
        _ => 5,                         // large class (wasteful placement)
    };
    // Reward lower classes (perfect fits), penalize dead-space classes.
    score -= (5 - class) as f64 * 6.0;
    if class == 1 {
        score += 12.0; // dead space penalty
    }
    if class == 0 {
        score -= 20.0; // perfect closure bonus
    }

    // Modulo arithmetic on post_residual: multiples of small harmonics (5, 10)
    // are more likely to be exactly filled by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.5;
    }
    // Odd remainders in the sliver band are hopeless.
    if class == 2 && post_residual % 5 != 0 {
        score += 4.0;
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // chain of exact fits
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            score -= 3.0;
            if next_post % 10 == 0 {
                score -= 4.0;
            }
            if next_post < 10 && next_post > 0 {
                score += 3.0; // would create dead space next step
            }
        } else {
            // next item cannot use this bin's leftover: leftover is stranded longer
            score += 2.0;
            if class == 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: worse than a good fit, better than dead space.
        score = bin_capacity as f64 * 0.5 + mean_residual * 0.3;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else if next_item_size > 0 && next_item_size >= half {
            score -= 8.0; // big item coming: fresh capacity is valuable
        } else if mean_residual > (half as f64) {
            score += 6.0; // existing bins still roomy, don't fragment capacity
        }
    }

    // Stream progression: early on, be conservative about dead space; late, prioritize closure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress; // slightly flatten preferences late in the stream

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (1..=9) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Tight-but-usable fit: reward small usable residuals.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 12.0;
    }
    // Large leftover space: mild penalty to avoid squandering big gaps on small items.
    if post_residual > 50 {
        score += 0.5 * (post_residual as f64 - 50.0);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 8.0 + 10.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score -= new_bin_bonus.max(-20.0);
    } else {
        score += 2.0 * open_bins_count as f64 / (1.0 + progress);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size + 10 {
            score -= 5.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // creates unusable gap for the known next item
        }
    }

    // Prefer bins below mean residual (saves tighter bins for tighter fits).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fill of the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0; // perfect 2-item chain
        } else if gap <= 5 {
            score -= 25.0; // near-perfect chain
        } else {
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted lookahead potential.
        score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual below mean are more precious;
    // wasting them is costly, using them well is rewarded.
    let rel = (bin_residual as f64) - mean_residual;
    if rel > 0.0 {
        score -= 0.05 * rel; // larger-than-average bin: prefer using it
    } else {
        score += 0.05 * (-rel); // smaller-than-average bin: slight penalty unless tight fit
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating small unusable dead space (post_residual in awkward zone).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Early in the stream, be slightly more willing to open new bins (keep flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: competitive only when current bins would leave big waste
        // or late in stream when consolidation matters.
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space relative to smallest plausible future item
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_penalty = (post_residual as f64 / 10.0).powi(2) * 0.35;
        score += dead_penalty * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty if we waste a big residual
            score += (post_residual.min(next_item_size) as f64) * 0.1;
        }
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64 * 0.55; // baseline cost of opening a bin
        score = new_bin_base;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // existing bin is last chance, prefer it
        }
        // Late in stream, prefer reusing open bins
        score += (step_index as f64 / total_items.max(1) as f64) * 15.0;
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;
        score -= open_bins_count.min(20) as f64 * 0.3;
    }

    // Prefer filling larger residuals with larger items (tighter packing)
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly coupled with stream progress
    let mut score = pr * (1.0 + progress * norm_pr * 2.0);

    // Smooth polynomial coupling: dead space penalty grows quadratically with progress
    let dead = norm_pr * norm_pr;
    score += 40.0 * dead * (0.5 + progress);

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead synergy: reward leaving space that the next item can use
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        let synergy = 1.0 - (gap / cap).min(1.0);
        score -= 15.0 * synergy * synergy * (1.0 + progress);
    }

    // Mild preference for fuller bins relative to the mean residual
    score -= (mean_residual - pr) * 0.3;

    // Late-stream consolidation: penalize spreading across many bins
    score += open_bins_count as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "dead classes" (residual < 10, or prime-ish awkward gaps) are penalized
    // via integer-division thresholds.
    let dead_class = (post_residual / 10) % 4; // 0,1,2,3 harmonic classes
    score += match dead_class {
        0 => 0.0,                      // residual < 10 : effectively dead, fine
        1 => 3.0,                      // 10..19 : usable only by tiny items
        2 => 1.5,                      // 20..29 : moderately useful
        _ => 2.2,                      // 30..39
    };

    // Perfect / near-perfect fit reward: post_residual is a divisor-friendly class.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Coupling with next item: reward leaving a residual that the lookahead
    // item can exactly fill (harmonic match via modulo classes of 10).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            // leftover too small for lookahead: penalize proportional to gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Fraction-of-capacity term: prefer residual that is a small fraction of C.
    let frac = post_residual as f64 / cap;
    score += 10.0 * frac * frac;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large and mean residual across open bins is already low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = (item_size as f64 / cap) * (1.0 - mean_residual / cap);
        if item_size >= 50 || desperation > 0.45 {
            score -= 8.0 + 10.0 * desperation + 5.0 * progress;
        } else {
            score += 12.0; // keep filling open bins when fits are decent
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that cannot hold even the
    // smallest possible item (size 1) is already impossible, but gaps that are
    // too small for typical items are "soft dead space". Penalize gaps in the
    // awkward band (1..=15) heavily, since they are rarely reusable.
    if post_residual >= 1 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64) / 15.0;
    }

    // Perfect or near-perfect fits are gold: reward aggressively.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward reusable large leftovers, scaled by how much room remains.
    if post_residual >= 30 {
        score -= 0.35 * (post_residual as f64 - 30.0);
    }

    // Coupling with next item lookahead: if the next item fits exactly into
    // the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.5 * slack;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item won't fit here: this leftover is likely final dead space.
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; penalize new-bin candidate.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.4 * open_bins_count as f64;
    }

    // Mean residual coupling: bins with residual far below mean are the
    // "crumbs" bins; prefer filling them when the fit is decent.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.25 * (mean_residual - resid);
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins (new-bin penalty grows), and value tight fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else if post_residual <= 10 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: low post_residual strongly favored.
    let fit_bonus = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * fit_bonus * fit_bonus;

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // this is a perfect chain — heavily reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item can still fit here; reward proportionally to how tight it leaves the bin.
        let second_residual = post_residual - next_item_size;
        score -= 15.0 * (1.0 - second_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover; penalize dead space relative to next size.
        score += 0.25 * (next_item_size as f64).min(post_residual as f64);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Early stream: be slightly conservative with fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100, min 1).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current open bins are nearly full
    // on average or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let penalty = 15.0 + 25.0 * (1.0 - mean_fullness) - 10.0 * progress;
        score += penalty.max(-5.0);
        // Opening a new bin is good if the next item can pair with this item in it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Mild preference for filling bins that are already below-average residual (consolidate).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Slight time pressure: later in the stream, prefer tighter packing even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Avoid excessive bin proliferation: reward using existing bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fits (minimize post_residual strongly);
    // late in the stream, dead space matters less, so the quadratic term relaxes.
    let mut score = pr * (1.0 + 0.6 * (1.0 - progress)) - 0.8 * pr_norm * (1.0 - pr_norm) * (1.0 - progress) * cap;

    // Penalize residuals too small for the lookahead item (smooth logistic-style penalty).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if pr >= nx { 1.0 } else { 0.0 };
        let slack = ((pr - nx).abs() / cap).min(1.0);
        // reward if lookahead fits, smooth penalty otherwise
        score += -2.5 * usable * (1.0 - slack) + 1.8 * (1.0 - usable) * (1.0 - slack);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty relative to mean residual: avoid wasting space in already-loose bins.
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate shaping: neutral-ish baseline with slight penalty so that
    // genuinely good fits into open bins win, but terrible fits open a new bin.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: leftovers that are themselves
    // "useful sizes" (multiples of small divisors of capacity) are less dead.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual by its residue mod 10 (harmonic bucket width).
    let residue_class = post_residual % 10;
    // Leftovers near multiples of 10 pack future integer-sized items better.
    score += (residue_class as f64) * 0.8;

    // Integer-division thresholds: leftover >= 50 keeps half a bin usable.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score -= 15.0;
    } else if post_residual >= quarter {
        score -= 5.0;
    } else if post_residual > 0 {
        // Small dead space penalty, stronger when it cannot fit the next item.
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward strongly; if it fits at all, mild reward; else penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Harmonic: how close next item comes to filling leftover.
            let fill_ratio = next_item_size as f64 / pr;
            score -= 20.0 * fill_ratio;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full on average or this is a large item late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / cap;
        let item_frac = item_size as f64 / cap;
        // Open a new bin for big items when existing bins are crowded.
        let open_bonus = item_frac * 30.0 * (1.0 - avg_fullness) - 30.0 * avg_fullness;
        score = cap - pr + 40.0 - open_bonus + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin anyway
        }
    }

    // Mild preference to fill bins with high residual (consolidate space).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use well
    // are heavily penalized. A residual below ~10 is effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // hard-to-fill gap
    }

    // Reward exact / near-exact fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit would leave dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 && post_residual > 0 {
            score += 45.0; // ...but not if it creates dead space
        }
    }

    // New-bin candidate handling: only attractive when existing bins would waste space
    if bin_residual == bin_capacity {
        // Slight base penalty so tight fits in open bins win
        score += 15.0;
        // But if all open bins would leave big dead space, opening is fine
        if post_residual >= 10 {
            score -= 20.0;
        }
        // Late in stream, fewer open bins is better; opening new bins is cheap then
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones tightly
    score += 0.6 * open_bins_count as f64;

    // Prefer bins whose residual deviates from the mean (consolidate waste)
    score -= (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 20.0;
    }
    // If next item would be blocked by this placement's dead space, penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain: post_residual exactly equals next item size.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 > nxt {
            // Next item fits after this placement: reward closeness of the gap.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would NOT fit in the leftover: penalize dead space,
            // worse when the leftover is small (unusable).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0; // tiny useless sliver
            } else {
                score += 5.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Relative to mean residual: placing into a below-average-residual bin
    // (tighter bin) is good, keeps loose bins available for future items.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Never prefer a brand-new bin unless existing fits are bad:
    // new-bin candidate has bin_residual == bin_capacity, give it a mild penalty
    // that tight-fit lookahead rewards can override.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Slight preference for filling bins earlier in the stream (consolidation).
    score += 0.01 * (post_residual as f64 / bin_capacity as f64) * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small post_residuals that are too small for the minimum
    // item size (1) are pure waste; residual < 10 is nearly unusable.
    if post_residual < 10 {
        score -= 25.0; // perfect closure of a bin is excellent
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead: reward if the next item fits into the post_residual (chaining),
    // penalize if next item is large and would need a fresh bin anyway.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else {
            // next item won't chain here; mild penalty scaled by how much it overshoots
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize dipping far below the mean residual (creating an outlier hole),
    // but only when the bin still has plenty of room left.
    if post_residual >= 20 {
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score += 0.15 * dev;
        }
    }

    // New-bin candidate handling: empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap early (few open bins) or late in the stream
        // when consolidation matters less; it is expensive when many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_cost = (open_bins_count as f64).ln() + 1.0;
        score += 18.0 * open_cost * (1.0 - 0.5 * progress);
        // If the item fits the empty bin with a lot of leftover, discourage it
        // unless no open bin fits well (fitting_bins_count == 0 means only this).
        if fitting_bins_count <= 1 {
            score -= 20.0; // allow new bin when alternatives are absent/poor
        }
    } else {
        // Slight preference for reusing existing bins to keep bin count low.
        score -= 3.0;
    }

    // Late-stream consolidation: as the stream ends, favor closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on post residual (dead space), scaled by stream progress
    let mut score = post * (1.0 + 1.5 * progress * norm_post);

    // Non-linear coupling: cubic interaction of normalized post residual with progress
    score += 20.0 * norm_post.powf(3.0) * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= (cap - post) * 0.3 * progress;

    // Last-chance bin bonus: strong smooth reward when it's the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    } else {
        // Mild penalty proportional to fitting competition
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer bins below mean residual (consolidate emptier bins) with smooth coupling
    score += 0.15 * (mean_residual - post) * (1.0 - progress);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = post - nx;
        if room >= 0.0 {
            score -= 8.0 * (1.0 - room / cap) * (0.3 + 0.7 * progress);
        } else {
            // penalize blocking the next item, softly
            score += 6.0 * (1.0 + progress);
        }
    }

    // New-bin candidate: penalize mildly so we prefer good fits, but allow opening
    // when open bins would create large dead space (natural via post term)
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        // discourage hoarding bins early
        score += 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Class tiers: dead space (< 10) is worst; small slivers slightly less bad.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect: unusable but item packed tightly
    } else if post_residual <= 20 {
        score += 15.0; // awkward small leftover
    } else if post_residual <= 50 {
        score += 5.0;  // moderate leftover, still reusable for mid items
    }

    // Non-linear penalty on fraction of capacity wasted (quadratic coupling)
    score += 40.0 * frac * frac;

    // Harmonic compatibility: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward, scaled by tightness of chain fit
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.15 * chain_tight;
        } else if next_item_size <= bin_residual {
            // next fits only if we DON'T place current item here: mild penalty
            score += 8.0;
        }
        // modulo harmonic: next_item_size divides nicely into residual classes
        let m = next_item_size % 10;
        if m == 0 && post_residual % 10 == 0 && next_item_size <= post_residual {
            score -= 5.0; // aligned decade classes chain cleanly
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when nothing fits well
    if bin_residual == bin_capacity {
        // penalize opening a new bin, more so late in the stream and with many open bins
        score += 45.0 + 0.05 * (open_bins_count as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // but allow new bin if current item is large and would leave bad residue elsewhere
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild preference to fill emptier bins first when residuals are similar
    if (bin_residual as f64) > mean_residual * 1.5 && bin_residual < bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (very small gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < item_size.min(20) {
        // gap too small for likely next items
        score += 25.0;
    }

    // Reward tight fits (small waste) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    // creating a gap that strands the stream.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin for this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage filling existing ones (applied to existing bins only).
    if bin_residual < bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score -= 4.0 * pressure;
    } else {
        // New-bin candidate: penalize slightly, but relax when open bins
        // are fragmented (low mean residual means poor future fits).
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 10.0 + 30.0 * fragmentation;
    }

    // Late in the stream, consolidate harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match reward: lookahead item fits with small leftover.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead-space penalty: post_residual too small for the lookahead item
    // (wasted space the lookahead cannot use).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Tight fits are good: small post_residual relative to capacity is rewarded.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: placing into a bin with residual near the
    // mean keeps balance; bins with unusually small residual are precious.
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many bins compete but none is a last chance, or item is huge).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            // Prefer existing bins when they fit; make fresh bin unattractive.
            score += 20.0;
            // Exception: huge items leaving tiny fragments elsewhere favor new bin.
            if item_size >= 70 {
                score -= 25.0;
            }
        }
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space relative to smallest conceivable future item
    let dead = post_residual as f64 / 100.0;
    score += 3.0 * dead * dead;

    // Tight fill ratio reward: prefer bins whose residual is well used
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill * fill;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Scarcity pressure: fewer fitting bins -> new bin more attractive
        let scarcity = (fitting_bins_count as f64).recip();
        // Lookahead: if next item is large, keep residuals big -> open new bin
        let lookahead_pressure = if next_item_size > 0 {
            (next_item_size as f64 / 100.0).powi(2) * 20.0
        } else {
            0.0
        };
        score = 40.0 + scarcity * 10.0 + lookahead_pressure
            - 10.0 * (1.0 - progress)
            + 0.5 * (mean_residual / 100.0);
    } else {
        // Penalize wasting large-residual bins on tiny items
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 5.0 * waste;

        // Lookahead synergy: reward leaving a residual that fits next item exactly-ish
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            if post_residual as f64 >= next_item_size as f64 {
                score -= 8.0 * (1.0 - gap / 100.0);
            } else {
                score += 4.0 * (gap / 100.0);
            }
        }

        // Fragmentation guard: many open bins with low mean residual -> avoid spreading
        if open_bins_count > 3 && mean_residual < 30.0 {
            score += 6.0;
        }

        // Late stream: prefer closing bins out (minimize residual) as stream ends
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score -= 5.0 * progress * (post_residual as f64 / 100.0).recip().min(3.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = r;
    score += 24.0 * norm_r * norm_r * (0.5 + 0.5 * progress);
    score -= 30.0 * norm_r * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit next item
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / cap;
        } else {
            score -= 6.0 * (next_item_size as f64 / cap) * norm_r;
        }
    }

    // Last-chance bonus: avoid opening a new bin when few fitting bins
    if fitting_bins_count == 1 {
        score -= 9.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(6.0);
    }

    // Mild pressure toward bins below mean residual (balance residuals)
    score += 4.0 * (r - mean_residual) / cap;

    // Late-stream preference to keep filling existing bins
    score += 10.0 * progress * norm_r;

    // Slight penalty for spreading across too many open bins
    score += 0.15 * open_bins_count as f64 * norm_r;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" residue
    // classes (multiples of common item sizes) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // Reward post_residuals that are harmonically divisible by small size classes.
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 20 == 0 { score -= 7.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 4.0; }

        // Penalize tiny dead-space bands (post_residual in awkward low ranges).
        if pr <= 5 { score += 12.0; }
        else if pr <= 10 { score += 6.0; }
    }

    // Integer-division threshold on next_item_size vs post_residual:
    // does the lookahead item fit into the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // Extra reward if leftover would still be harmonically clean after next item.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
            if pr2 % 5 == 0 { score -= 1.5; }
        } else {
            // Next item cannot follow into this bin: penalize proportionally to the mismatch.
            let mismatch = (next_item_size - pr) as f64;
            score += 3.0 + mismatch * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (mean residual high relative to capacity) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score -= 2.0; // baseline attractiveness of a fresh bin
        if fragmentation > 0.5 { score -= 4.0 * (fragmentation - 0.5); }
        if progress > 0.8 { score -= 1.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 3.0; }
    }

    // Mild preference for tighter existing bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item (<= ~10) are essentially unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect or near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual is "consumed" proportionally well.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into fewer bins
    // when many are already open, unless the fit is poor.
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - fill_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item can fit into the post-residual, this bin
    // remains valuable; if not, the leftover space risks becoming dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual < 10 {
            score += 15.0;
        }
    }

    // Mean residual context: when open bins are generally roomy, prefer
    // filling the tightest ones (deviation from mean residual).
    let residual_dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * residual_dev * (1.0 - fill_ratio);

    // Late in the stream, tighten up: dead space matters more since fewer
    // opportunities remain to reuse it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate (empty bin): neutral base; only attractive when the
    // item is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        score -= 5.0 + 10.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is golden.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();

        // Exact lookahead fit: strong reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 30.0 - diff * 4.0;
        } else {
            // Mismatch penalty grows with distance from next item size.
            score += diff * 0.8;
        }

        // If next item can't fit here anyway, mild penalty for wasting lookahead.
        if pr < nxt {
            score += 8.0;
        }
    }

    // Dead-space penalty: very small post_residual that fits nothing (min item 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer tight fits relative to mean residual.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad
    // residual or lookahead mismatch; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 35.0
            + (open_bins_count as f64) * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            new_bin_score -= 40.0; // fresh bin perfectly set up for next item
        }
        if item_size >= 70 {
            new_bin_score -= 15.0; // huge items pair well with a fresh bin
        }
        score = score.min(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong bonus.
    let fit_ratio = post_residual as f64 / cap;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that can never be used by typical items (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, big bonus for this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && (bin_residual as u32) >= next_item_size && post_residual > 0 {
        // Placing here destroys a slot for the next item: penalize mildly.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer filling bins with larger residuals among many open bins (balance load).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // Many open bins: encourage closing out (filling) existing bins rather than spreading.
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64).ln() * fit_ratio;
    }

    // New-bin candidate: make it moderately attractive only when current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - fit_ratio); // fit_ratio == 1 here, so adds 0
        score -= 5.0 * (1.0 - (post_residual as f64 / cap)); // = 0 for empty bin
        score += 12.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits (small post_residual); later, allow slightly
    // larger residuals to keep flexibility, so weight shifts smoothly.
    let mut score = pr * (1.0 + 0.8 * progress) - 20.0 * progress * norm_pr * (1.0 - norm_pr);

    // Non-linear interaction: dead space penalty grows super-linearly when the
    // residual becomes too small to be useful for typical items.
    let dead = if pr > 0.0 { (1.0 - norm_pr).powf(3.0) } else { 0.0 };
    score += 15.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 12.0 * (ni / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 8.0 * (1.0 - pr / ni) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smoothly scaled by how full the bin already is).
    if fitting_bins_count == 1 {
        let fill = 1.0 - norm_pr;
        score -= 25.0 * fill * (0.5 + 0.5 * progress);
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * norm_pr * 5.0;

    // Mean-residual coupling: prefer bins whose residual is close to the mean
    // (keeps residual distribution balanced), penalize outliers smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins fit, but less when the stream is nearly done.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0 * (fitting_bins_count as f64).min(3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) are perfect,
    // but small-but-unusable gaps for typical items are penalized.
    // Class boundaries via integer division on post_residual.
    let class = post_residual / 10; // 0..10 harmonic classes
    match class {
        0 => { score -= 50.0; }          // near-perfect fill
        1 => { score -= 20.0; }          // 10..19: decent leftover
        2 => { score -= 10.0; }
        3 => { score -= 5.0; }
        4 => { score += 2.0; }           // mid-range leftover: mediocre
        5 => { score += 4.0; }
        6 => { score -= 3.0; }           // 60..69: fits most mid items
        7 => { score -= 6.0; }
        8 => { score -= 8.0; }
        _ => { score -= 2.0; }           // large residual: nearly-empty bin use
    }

    // Modulo coupling: residual divisible by common item sizes is reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        else if post_residual % 2 == 0 { score -= 1.0; }
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if next_item_size == post_residual { score -= 12.0; }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; if this bin is the only fitting bin, penalize wasting it
        if fitting_bins_count == 1 { score += 15.0; }
    }

    // Last-chance bonus: only one bin can fit the item — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // fits poorly everywhere else (high post_residual in existing bins is fine).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        // penalize new bins early on; relax as stream fills and bins accumulate
        score += 30.0 / pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big next item: fresh bin keeps flexibility
        }
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    // Mean residual coupling: when open bins are generally full, prefer tight fits more.
    if frac < mean_residual / bin_capacity as f64 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= 50 {
        score -= 15.0;
    } else if post_residual < 30 {
        // Mid-range dead zone: mildly penalize unusable-ish gaps.
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item won't fit here -> residual becomes dead space
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> consolidate into existing ones.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins) to keep large residuals available for large items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin is attractive only when
    // existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; opening is preferred over wasting space
        // in near-full bins, but discouraged when a good fit exists.
        score = 45.0 + item_size as f64 * 0.2;
        if post_residual == 0 { score -= 60.0; } // unreachable, keep safe
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual exactly matches the next item,
    // penalize when post_residual can't fit the next item (dead space risk).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if next <= post {
            // next item fits: reward tight matches
            score -= 0.9 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 6.0; // perfect 2-chain
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted gap
            score += 0.5 * (next - post) / bin_capacity as f64;
        }
    }

    // Compare post_residual to mean residual: avoid making a bin much tighter than average
    score += 0.3 * (mean_residual - post as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * open_bins_count as f64;
    }

    // Slight preference for filling bins more completely early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.2 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
