            // extra reward for near-perfect two-item packing
            let chain_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else if next_item_size > bin_residual {
            // next item can't fit here anyway; mild penalty for wasting big residual
            score += 3.0;
        } else {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // New-bin candidate handling: prefer reusing bins that fit well;
    // only favor a new bin when residuals are fragmented.
    if bin_residual == bin_capacity {
