        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count >= 1 {
            // discourage opening new bins when alternatives exist
            score += 18.0;
        }
        // open new bins more readily early in the stream or when open bins are full-ish
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 0.5 {
