        }
        if open_bins_count > 20 {
            score += 6.0 * ((open_bins_count as f64 - 20.0) / 20.0).min(2.0);
        }
    }

    // Prefer filling bins that are already below-average residual (consolidate waste).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild preference for keeping the number of open bins small late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
