    }

    // Exact fit is ideal
    if pr == 0 {
        score -= 50.0;
    }

    // Integer-division thresholds: post_residual in "half" vs "quarter" classes
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr <= quarter && pr >= 10 {
        score -= 4.0; // small but still usable residual: good compaction
    } else if pr > half {
        score += 3.0; // leaving more than half empty is wasteful
    }

    // Coupling with next item lookahead (k=2): harmonic compatibility
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0; // next item exactly fills this bin
        } else if next_item_size < pr {
            // modulo-class compatibility: next item leaves again a small residue
            let chain = pr % next_item_size.max(1);
            if chain < 10 {
                score -= 3.0;
            }
            score -= 1.5; // next item can still use this bin
        } else {
            score += 2.0; // next item won't fit here; residual likely stranded
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // opening a new bin wastes (capacity - item_size); compare against mean residual
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 0.9;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
