        let mut new_bin_score = 70.0 + 20.0 * progress;
        new_bin_score -= 0.3 * fragmentation;
        if fitting_bins_count <= 2 {
            new_bin_score -= 30.0; // few alternatives -> opening new bin more attractive
        }
        // Late in stream, prefer consolidating into open bins
        new_bin_score += 40.0 * progress;
        score = score.max(new_bin_score.min(score)) * 0.0 + new_bin_score;
    } else {
