    // late in the stream, compact residual space is worth more.
    let norm_pr = pr / cap;
    let phase = progress * std::f64::consts::PI;
    let urgency = 0.5 * (1.0 - phase.cos()); // smooth 0..1 ramp
    score += 12.0 * urgency * norm_pr * norm_pr * cap * 0.1;

    // Reward tight fits: penalize large post_residual relative to item size smoothly.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that cannot serve the lookahead item smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 10.0 * gap * gap * cap * 0.1;
    }

