    score += (open_bins_count as f64).powf(1.3) * 0.05;

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic).
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into deciles of capacity.
    let post_class: u32 = (post_residual * 10) / bin_capacity; // 0..10 integer division class
    // Dead-space penalty grows super-linearly for small unusable classes (< item sizes 10..80).
    match post_class {
        0 => score += 60.0,
        1 => score += 34.0,
        2 => score += 18.0,
        3 => score += 8.0,
        4 => score += 2.0,
        _ => {}
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post residual (harmonic chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        if chain_waste == 0 {
            score -= 45.0; // chain-perfect: this bin absorbs both items exactly
        } else {
            let chain_class: u32 = (chain_waste * 10) / bin_capacity;
            score -= 20.0 - 4.0 * chain_class as f64;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for lookahead item: penalize proportionally (dead space blocks chain).
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer empty bin when current fit is bad.
    if bin_residual == bin_capacity {
        // Neutral baseline; subtract a bit when open bins are congested.
        score -= 5.0;
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // Early stream: prefer new bins slightly to build capacity diversity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Mild penalty for wasting a large-residual bin on a tiny item.
    if item_size < 20 && bin_residual > 60 {
        score += 6.0;
    }

    // Spread-aware term: prefer bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        // penalize gaps too small to fit even the smallest plausible item
        if post_residual < 10 {
            score += 60.0 * (1.0 - dead);
        } else if post_residual < 20 {
            score += 25.0 * (1.0 - dead);
        } else {
            score += 8.0 * dead;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap that cannot host the next item: dead space risk
        score += 12.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    let pressure = (open_bins_count as f64) / ((open_bins_count as f64) + 4.0);
    score += 15.0 * pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // base penalty so open bins are usually preferred
        score += 20.0;
        // but if item leaves a large residual in a new bin, that's fine early on
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if next item is large, a fresh bin can be attractive
        if next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Mild preference for tighter existing bins (small residual relative to mean).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward near-exact fills.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fits the post
    // residual, this is a chained perfect placement — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            if gap == 0.0 {
                score -= 800.0;
            } else if gap <= 5.0 {
                score -= 250.0;
            } else if gap <= 10.0 {
                score -= 100.0;
            } else {
                // next item fits but leaves more dead space: mild penalty
                score += gap * 0.3;
            }
        } else {
            // next item cannot fit here; penalize proportional to overshoot
            score += (nxt - post_residual as f64) * 0.5;
        }
    }

    // Compare post_residual to mean residual: leaving much more space than
    // average wastes bin capacity elsewhere; leaving less is efficient.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
        if post_residual <= 15 {
            score -= 100.0;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent
    // fit (large post_residual everywhere) or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // A fresh bin scores as its full residual; penalize slightly so it
        // only wins when existing bins would leave huge dead space.
        score += 40.0 + 60.0 * progress;
        if fitting_bins_count > 1 {
            score += 150.0;
        }
        // If next item is huge, opening a fresh bin may be wise.
        if next_item_size as f64 >= 0.7 * cap {
            score -= 80.0;
        }
    }

    // Mild penalty for very tight bins when many bins are open (fragmentation).
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins when existing fits are decent,
    // but allow it when the fit would leave large unusable residue or few bins open.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity as f64 - item_size as f64);
        let mut newbin_score = waste * 0.9;
        if fitting_bins_count == 0 {
            newbin_score -= 100.0; // no alternative
        }
        if post_residual >= 10 {
            newbin_score -= 15.0; // residue still usable for future items
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        newbin_score += 20.0 * progress;
        // Many open bins with slack: discourage new bin.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            newbin_score += 12.0;
        }
        score = newbin_score;
        return score;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 4.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    score -= (bin_residual as f64 / bin_capacity as f64) * 6.0;

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins that are outliers (very full or very empty handled above).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling
    let mut score = pr;
    score += 40.0 * fit_norm * fit_norm;
    score += 30.0 * fit_norm * fit_norm * fit_norm;

    // Late in the stream, dead space is more costly
    score += 60.0 * fit_norm * fit_norm * progress;

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 15.0 * progress;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize bins far below mean residual (wasteful large holes)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Make the fresh-bin candidate less attractive unless residual is tiny
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item relative to capacity quarters
    let quarter = bin_capacity / 4;
    let item_class = item_size / quarter.max(1);
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / quarter.max(1) };

    // Perfect-fit reward: post_residual exactly in "useful" harmonic buckets
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual >= 10 && post_residual < quarter {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic complementarity: does post_residual invite next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or leaves a good remainder
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 90.0;
            } else if next_post < 10 {
                score -= 45.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize dead space growth
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Modulo-structure on post_residual: values that tile well with common sizes
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0; // multiple of 10 tiles with round item sizes
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Integer-division thresholds: penalize leaving a sliver in mid-range classes
    if item_class >= 2 && pr > 0 && pr < quarter / 2 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is very full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) / (mean_residual.max(1.0) / bin_capacity as f64 + 1.0);
        score += 55.0 + 30.0 * progress + pressure * 0.1;
        // allow new bin only when item is large and won't waste much elsewhere
        if item_class >= 3 {
            score -= 40.0;
        }
    }

    // Mild preference for fuller bins (smaller residual) beyond raw post_residual
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mean-residual coupling: if this bin is much emptier than average, deprioritize slightly
    let res_f = bin_residual as f64;
    if res_f > mean_residual * 1.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A small but nonzero post_residual is a "dead gap": too small for any
    // future item (items >= 1, but tiny gaps rarely reusable). Penalize hard.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - pr) / 10.0; // up to +40 for near-useless slivers
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty scaled by how "wasted" the gap is relative to capacity.
    let waste = pr / bin_capacity as f64;
    score += 15.0 * waste * waste; // quadratic: large leftovers mildly bad, tiny leftovers handled above

    // --- Open bins pressure ---
    // Encourage filling existing bins when many are open (avoid bin sprawl).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure;

    // --- Last-chance bonus ---
    // If this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild tie-break toward tighter bins among many candidates
        score -= 2.0;
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // placing here creates a gap that next item leaves as dead space
            score += 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // next item cannot use this gap at all -> dead space confirmed
            score += 12.0;
        }
    }

    // --- Mean residual context ---
    // Prefer bins tighter than average (below-mean residual = well-packed).
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff; // lower residual than mean -> lower score

    // --- New-bin candidate handling ---
    // Empty bin: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin loses to decent fits.
        score = 55.0 + 2.0 * (open_bins_count as f64);
        // If nothing else can fit the item, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in the stream, prefer squeezing into existing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is large and this new bin would serve it, slight bonus.
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of post_residual with next_item_size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Reward tight lookahead match, strongest when exact.
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if diff == 0.0 {
            score -= 40.0; // exact 2-step fit bonus
        }
        // Penalize leaving space the next item cannot use at all (dead space).
        if next_item_size as u32 > post_residual {
            score += 15.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    } else {
        // Last item: just prefer minimal leftover.
        score += 5.0;
    }

    // Penalize very small post_residual (fragmented dead space) unless exact next fit.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer filling bins with residual below the mean (tighten tight bins).
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins usually win; relax late in stream or many open bins.
        score += 60.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // If next item is large, a fresh bin is more valuable.
        score -= 0.1 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill * fill;

    // Penalize dead space: small post_residual that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits in post_residual, reward it.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 4.0;
        } else if next_item_size as u32 > post_residual {
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            -20.0
        } else if fitting_bins_count == 1 {
            -2.0
        } else {
            3.0
        };
        // Larger items favor fresh bins slightly more.
        score += desperation + (item_size as f64 / 40.0) * (1.0 - desperation.abs() / 20.0);
    }

    // Global state: penalize placing into bins when mean residual is small
    // (fragmented state) unless this bin is a good fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (mean_residual - post_residual as f64).abs() * (1.0 - progress);

    // Time horizon: early on, keep bins tight; late, prefer consolidation.
    if progress > 0.7 {
        score -= 1.5 * fill;
    }

    // Small penalty per open bin to encourage reuse over proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 20.0 * norm_pr * (1.0 - norm_pr);

    // Smooth non-linear interaction: reward tight fits more as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth ramp)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 5.0 * (gap / cap) * (1.0 + progress);
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let fit_frac = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 10.0 * fit_frac * fit_frac;

    // Slight preference for consolidating into bins already open
    score += 0.05 * (open_bins_count as f64);

    // Diverge from mean residual smoothly
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Class of post residual via integer division thresholds
    let post_class = post_residual / eighth.max(1); // 0..=8 harmonic class
    let next_class = next_item_size / eighth.max(1);

    // Perfect fit: residual becomes exactly a harmonic class boundary (0, 25, 50, 75)
    if post_residual == 0 || post_residual == quarter || post_residual == 2 * quarter || post_residual == 3 * quarter {
        score -= 12.0;
    }

    // Dead space: post_residual small but nonzero and not matching next item
    if post_residual > 0 && next_item_size > post_residual {
        // unusable leftover relative to lookahead
        score += (next_item_size - post_residual) as f64 * 0.8;
        // modulo harmonic penalty: dead space in awkward classes
        let dead = post_residual % 10;
        score += dead as f64 * 0.3;
    }

    // Reward when next item fits exactly into post_residual (chained packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 6.0;
        if slack == 0 {
            score -= 8.0; // perfect chain
        } else {
            score += slack as f64 * 0.15;
        }
    }

    // Harmonic class matching: post_residual class equals next_item_size class
    if next_item_size > 0 && post_class == next_class && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tightest (post_residual term already does this)
        score += fitting_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: empty bin should only win for large items or bad fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize opening new bin, more so early when open bins are empty-ish
        let mut new_bin_penalty = 20.0 + 10.0 * (1.0 - progress);
        // but if item is huge relative to mean residual, opening may be wise
        let tight_fit = (mean_residual - item_size as f64).abs() < 5.0;
        if tight_fit && open_bins_count > 0 {
            new_bin_penalty += 5.0;
        }
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 2 * quarter as u32 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for bins below mean residual (tighter bins get priority)
    score += (mean_residual - post).max(0.0) * 0.1;

    // Small modulo-structured tiebreak on post_residual to diversify class usage
    let phase = (post_residual % 7) as f64;
    score += phase * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to host the
    // smallest plausible future item are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0 * (10.0 - post_residual as f64) / 10.0
        } else if post_residual < 20 {
            25.0 * (20.0 - post_residual as f64) / 10.0
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    score -= 8.0 * (item_size as f64 / (bin_residual as f64).max(1.0));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing space.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but relax if current bin would leave bad dead space.
        score += 20.0 + pressure;
        if post_residual < 10 && post_residual > 0 && fitting_bins_count == 1 {
            score -= 25.0;
        }
    } else {
        score -= 0.5 * pressure * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap: extra dead-space penalty.
        score += 5.0 * (post_residual as f64 / 20.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post-residual
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item fits here: mild reward proportional to closeness
            score -= 200.0 / (1.0 + diff as f64);
        } else {
            // next item would leave dead space if placed here
            score += 0.5 * diff as f64;
        }
    }

    // Penalize post_residual that is small but unusable (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Slight aversion to opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 40.0 + 0.1 * open_bins_count as f64;
    }

    // Progress-based tightening: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if post residual is too small for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Time horizon: late in the stream, prefer filling existing bins tightly
    // rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> discourage
    // scattering; prefer bins below mean residual (denser bins).
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * dev;
    }

    // New-bin candidate: only attractive when nothing fits well or item is huge.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 35.0 * scarcity - 20.0 * big_item;
    }

    // Small regularizer toward perfectly full bins.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: quadratic/cubic shaping of post-residual scaled by progress
    score += (norm_pr * norm_pr) * (20.0 + 40.0 * progress);
    score -= (norm_pr * norm_pr * norm_pr) * 30.0 * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize small dead space that becomes unusable (smooth hinge-like polynomial)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 10.0 {
            let x = (10.0 - gap) / 10.0;
            score += x * x * 15.0;
        }
        // Reward leaving room for the next item (smooth)
        if gap >= 0.0 {
            let g = (gap / cap).min(1.0);
            score -= g * g * 8.0;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Deviation from mean residual: prefer bins near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: make empty bins less attractive unless residual is poor
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward, zero dead space.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead harmony: if the next item exactly fills the leftover space.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits here: mild reward scaled by tightness
        score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // Penalize tiny unusable slivers (dead space below min item size 1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Harmonic class of residual: prefer residuals divisible by 10
    // (aligns with common item granularity classes 10..80).
    let r = (post_residual % 10) as f64;
    score -= (5.0 - r) * 0.8;

    // Larger leftover residuals are more reusable later.
    if post_residual > 50 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly so open bins are preferred
    // unless their residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Early in the stream, keep mean residual low (consolidation pressure).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (1.0 - t);

    // Slight preference to fill bins with fewer alternatives (reduces bin spread).
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band are heavily penalized.
    let dead_low = 1.0;
    let dead_high = (0.25 * bin_capacity as f64).max(10.0);
    if post_residual as f64 >= dead_low && post_residual as f64 <= dead_high {
        // Deepest in the dead zone (small post_residual) => worst.
        let depth = 1.0 - (post_residual as f64 - dead_low) / (dead_high - dead_low + 1.0);
        score += 40.0 * depth;
    }

    // Reward tight fits (small post_residual outside dead zone).
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual as f64 > dead_high {
        score -= 5.0; // roomy residual may still be usable
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        // But if next item is large and this item leaves a big residual, opening a fresh
        // bin can be attractive: reduce the penalty.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 12.0;
        }
    }

    // Open-bin pressure: mildly discourage accumulating many open bins.
    score += open_bins_count as f64 * 0.8;

    // Lookahead coupling: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // perfect match for the NEXT item
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // next item fits exactly after placing current one, or fits comfortably
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving awkward residual
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // last item: prefer tightest fill
        score -= 40.0;
    }

    // Relative-to-mean dead space penalty
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual as i64 - next_item_size as i64 > 0 { 0.0 } else { 1.0 };
        score += 45.0 * poor_fit + 0.25 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progress-based tie-breaking: later in stream, prefer filling existing bins tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Reward high fill ratio
    score -= 50.0 * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 40.0 * tight * tight;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 8.0 + 0.5 * nxt;
        } else {
            // Reward bins whose leftover can host the next item.
            score -= 6.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        }
        // Perfect pair: item + next item exactly fills residual.
        if (item_size + next_item_size) as f64 == bin_residual as f64 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Early in stream: prefer spreading into fresh bins less; late: fill aggressively.
    score += (1.0 - t) * 6.0 * (post_residual as f64 / cap);
    score -= t * 10.0 * (1.0 - (post_residual as f64 / cap));

    // Penalize opening new bins when many bins are open with slack.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
    } else {
        // Prefer bins with residuals close to the item (best-fit style).
        let gap = (bin_residual - item_size) as f64;
        score += 0.15 * gap;
        // Slight reward for using bins that deviate from mean residual (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * dev;
    }

    // Mild penalty for very small unusable leftovers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling: post_residual weighted by progress
    score += 8.0 * (post / cap) * (post / cap) * (progress - 0.5).abs() * 2.0;

    // Reward tight fits (small post_residual) with a quadratic bonus
    score -= 6.0 * (1.0 - post / cap).powi(3);

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 10.0 * (1.0 - slack / cap).powi(2);
        } else {
            score += 4.0 * (nxt / cap);
        }
    }

    // Last-chance bin before opening a new one: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating dead space far below mean residual (fragmentation)
    if post > 0.0 && (post - mean_residual).abs() > cap * 0.25 {
        score += 3.0 * ((post - mean_residual).abs() / cap);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * (open_bins_count as f64 / (1.0 + progress * 10.0)) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes
    // (small dead space, or divisible-friendly chunks like 25/50).
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // modulo-25 harmonic class: residuals near multiples of 25 pair well with
        // typical item sizes (25/50/75).
        let m25 = post_residual % 25;
        let m50 = post_residual % 50;
        if m25 == 0 {
            score -= 18.0;
        } else if m50 == 0 {
            score -= 20.0;
        } else if m25 <= 5 || m25 >= 20 {
            score -= 6.0; // near a harmonic boundary
        } else {
            score += 5.0; // awkward middle residual
        }

        // Small residuals are dead space; penalize but reward tight fits.
        if pr <= 10.0 {
            score -= 10.0; // tiny dead space is fine
        } else if pr <= 25.0 {
            score += pr * 0.4;
        } else {
            score += pr * 0.25;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // next item fits here: prefer bins where leftover stays harmonic
            let after = post_residual - next_item_size;
            if after % 25 == 0 || after == 0 {
                score -= 15.0;
            }
            score -= 4.0;
        } else {
            // next item won't fit here; penalize more if this bin was the only option
            score += 6.0;
            if nx > pr + 20.0 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Fraction of capacity filled by this placement.
    let fill = item_size as f64 / cap;
    score -= fill * 12.0;

    // New-bin candidate: prefer it only when existing bins are all crowded
    // (high mean residual would mean loose bins -> keep using them).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - mean_residual * 0.5 - progress * 10.0 + open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., a loose bin) is good; tight bins get penalized slightly.
    let resid_frac = bin_residual as f64 / cap;
    if resid_frac > mean_residual / cap {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer filling the bin tightly.
    let mut score = post;

    // Strict dead-space penalty: residual gaps below the minimum item size are pure waste.
    let min_item = 1.0f64.min(cap); // interface: sizes in 1..=100
    let dead_threshold = 10.0f64; // smallest plausible item in classic streams
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Post residual cannot host next item: penalize proportionally to how close it is.
        score += 6.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading (favor new bin
    // only for poor fits); when few bins are open, mildly favor consolidation.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post / cap) * 10.0;

    // New-bin candidate handling: only attractive when the current item fits poorly
    // everywhere (post residual would be large dead space relative to mean residual).
    if bin_residual == bin_capacity {
        // Empty bin: score = full residual minus consolidation incentive.
        score = cap - 12.0 + pressure * 4.0;
        if fitting_bins_count == 1 {
            // Some open bin is a last chance; make new bin unattractive.
            score += 40.0;
        }
        if post_residual == 0 {
            score -= 20.0; // (defensive; empty bin can't have post_residual 0 for real items)
        }
    }

    // Mild time decay: later in the stream, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: prefer bins whose post_residual exactly
    // matches the next item's size (perfect chain), or at least fits it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect two-step match
        } else if post_residual >= next_item_size {
            score -= 25.0; // next item still fits
        } else {
            // dead space relative to next item: penalize proportionally
            let gap = nxt - post_residual as f64;
            score += 0.8 * gap;
        }
    }

    // Penalize small unusable leftovers relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual) but keep lookahead dominance
    score -= 0.05 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild pressure relative to mean residual: prefer bins tighter than average
    score += 0.15 * (mean_residual - post_residual as f64);

    // Early in stream, be slightly more willing to open bins for large items
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to item size.
    let waste_ratio = post_residual as f64 / (bin_capacity as f64).max(1.0);
    score += waste_ratio * waste_ratio * 40.0;

    // Penalize bins whose residual is barely above item size unless it's a perfect fit
    // (fragmentation risk): residual slightly larger than item leaves dead slivers.
    let slack = bin_residual as f64 - item_size as f64;
    if slack > 0.0 && slack < 5.0 {
        score -= 8.0; // near-perfect fit, strongly favor
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fills the bin almost completely afterwards.
        let post2 = post_residual as f64 - next_item_size as f64;
        if post2 < 5.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: mild penalty for stranding space.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: proportional to remaining stream length.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let horizon = 1.0 - progress;
        score = item_size as f64 * 0.8 + 30.0 * horizon;
        // If the item fits poorly everywhere, a new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Small items into a fresh bin are wasteful; large items are fine.
        if item_size < 30 {
            score += 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Prefer bins with residual close to item size (best-fit core), scaled smoothly.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * progress;
    score += 6.0 * coupling;

    // Penalize near-full bins less as stream progresses (tight packing late)
    let tightness = (cap - pr) / cap;
    score -= 4.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 3.0 * fit_quality * fit_quality;
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: mildly penalize early, allow late when open bins are poor
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs() / cap;
        score += 8.0 * (1.0 - progress) - 5.0 * spread * progress;
    }

    // Deter wasteful large residuals left in crowded systems
    let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 2.0 * norm_pr * crowd;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: capacity fractions (1/2, 1/3, 1/4 of C)
    let cap = bin_capacity as f64;
    let half = cap / 2.0;
    let third = cap / 3.0;
    let quarter = cap / 4.0;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Penalize dead space below smallest item (1)
    score += (post_residual as f64).powi(2) / (2.0 * cap);

    // Reward placing large items into bins whose residual matches their class
    let pr = post_residual as f64;
    if pr <= quarter {
        score -= 30.0; // near-full bin is good closure
    } else if pr <= third {
        score -= 10.0;
    } else if pr <= half {
        score += 5.0; // half-empty bins should stay flexible
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size as f64 == pr {
            score -= 500.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 40.0;
        } else {
            score += 20.0; // next item won't fit here; bin becomes dead
        }
        // Modular harmony: next item size mod 10 classes
        let nmod = next_item_size % 10;
        if nmod == 0 && (post_residual % 10) == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless current item is huge
    if bin_residual == bin_capacity {
        let base = 120.0;
        let big_item_bonus = if item_size > bin_capacity / 2 { 0.0 } else { 80.0 };
        score += base + big_item_bonus
            - (open_bins_count as f64) * 2.0
            - (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size as u32 > bin_residual {
            score -= 60.0; // next item won't fit a fresh bin either way, irrelevant
        }
    }

    // Slight preference for tighter bins overall
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual exactly matches next item (lookahead fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap just below next item size (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // and make new bins less attractive.
    let pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: add pressure; allow it only when few alternatives exist
        // or the fit elsewhere would be terrible.
        score += 20.0 + pressure;
        if fitting_bins_count <= 1 {
            score -= 60.0; // last chance: new bin is fine
        }
        if post_residual as f64 > mean_residual + 30.0 {
            score += 10.0;
        }
    } else {
        // Existing bin: slight reward when it is one of few fitting bins.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer tighter bins (lower residual relative to mean) mildly.
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Late in the stream, tighten consolidation further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect 2-step lookahead matches
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 40.0;
        if after_next == 0 {
            score -= 60.0;
        } else if after_next < 10 {
            score -= 20.0;
        }
        // bonus when after-next residual is tiny relative to capacity
        score -= 0.3 * (bin_capacity as f64 - after_next as f64) / bin_capacity as f64;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to mismatch
        let gap = (next_item_size - post_residual) as f64;
        score += 0.8 * gap;
    }

    // Penalize creating small unusable dead space (< 10 = minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: mild penalty so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if lookahead matches an empty bin perfectly, allow it
        if next_item_size > 0 && next_item_size == item_size {
            score -= 20.0;
        }
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual relative to capacity (dead space).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * frac * frac;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize wasting a bin that can't host the lookahead item.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: later in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling this bin.
    if open_bins_count > 0 {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // new bin still useful for future items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: tight fit is good (low post_residual => low score), non-linearly
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling with stream progress: early on, keep bins flexible
    // (penalize tiny residuals more), late in stream, exploit tight fits harder.
    let flex = 1.0 - progress;
    score += flex * 12.0 * norm_post * (1.0 - norm_post);
    score -= progress * 6.0 * norm_post * norm_post;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            // post_residual cannot host next item: penalize dead space
            score += 4.0 * norm_post * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins over spreading
    score += 0.3 * (open_bins_count as f64).ln() * norm_post;

    // Deviation from mean residual: prefer bins close to mean (balanced packing)
    score += 0.5 * (post - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: multiples of 10 are "clean" slots.
    let harmonic = post_residual % 10;
    score += (harmonic as f64) * 0.9;

    // Perfect fit bonus (post_residual == 0) heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small unusable dead space (1..=9) is penalized beyond its raw size.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Classify post_residual via integer division thresholds.
    let q = post_residual / 10;
    score += match q {
        0 => 5.0,
        1 => -3.0,
        2 => -6.0,
        3 => -4.0,
        4 => -2.0,
        _ => 0.0,
    } * (bin_capacity as f64 / 100.0);

    // Lookahead coupling: if next item can fit exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Prefer leftover that leaves a good harmonic class for the next item.
            let next_left = post_residual - next_item_size;
            if next_left % 10 == 0 {
                score -= 10.0;
            }
            score += (next_left % 5) as f64 * 1.5;
        } else {
            // Next item won't fit here: mildly penalize tight leftovers.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins when many bins are open (reduce fragmentation).
    let fill_frac = (item_size as f64) / (bin_capacity as f64);
    score -= fill_frac * 8.0;

    // Mild preference for bins with above-average residual when stream is early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) > mean_residual {
        score -= (1.0 - progress) * 3.0;
    } else {
        score += (1.0 - progress) * 1.5;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size > 70 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // dead space that even the next item can't use
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: with many open bins, prefer filling
    // existing bins over spreading; with few bins, opening new is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * (2.0 + 4.0 * progress);

    // New-bin candidate: baseline slightly below mean residual so it is only
    // chosen when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = mean_residual * 0.45 + 14.0 + bin_pressure * 1.5 - 20.0 * progress;
        if fitting_bins_count <= 1 {
            score += 30.0; // never open new bin if only one fits
        }
    } else {
        // Mild preference for bins tighter than the average residual.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (perfect 2-step fill).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: post_residual == next_item_size -> big bonus.
        if gap == 0.0 {
            score -= 40.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // Next item can still fit here: reward closeness.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize dead space proportionally.
            score += 8.0 * (gap / bin_capacity as f64);
        }
        // Slight preference to chain placements when bin is well used.
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // tiny unusable sliver -> bad
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 10.0 * (1.0 - progress) - 5.0 / pressure;
        // If item is huge relative to capacity, opening fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
        // If next item is large, keep some slack via a fresh bin.
        if next_item_size >= 60 && post_residual < 40 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 10.0 - 0.08 * slack_after_next as f64;
    }
    // If next item cannot fit here, penalize more when it leaves large dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.06 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins exist with room.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    }

    // Prefer bins whose residual is above the mean (avoid fragmenting already-small bins).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Mild penalty for leaving awkward residuals (just above typical small item sizes).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 6.0; // tiny dead space is wasted capacity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear waste penalty: squared normalized post_residual, growing with progress
    let pr_norm = post_residual as f64 / cap;
    score += 3.0 * pr_norm * pr_norm * (1.0 + progress);

    // Reward tight fits: item filling most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= 4.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead coupling: penalize leaving residuals that don't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 2.5 * (nxt - post_residual as f64) / cap * (1.0 + progress);
        } else {
            score -= 1.5 * (1.0 - ((post_residual as f64 - nxt) / cap).powi(2));
        }
    }

    // Smooth interaction: bins far below mean residual get a mild preference
    score -= 0.5 * ((mean_residual - post_residual as f64) / cap);

    // Penalize proliferation of open bins mildly as stream progresses
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - fill.max(0.0)) + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by integer division into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: residuals that are too small to host typical items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic band rewards: post_residual falling in "useful" bands (able to host
    // mid-sized items) get discounted. Bands via integer division thresholds.
    let band = post_residual / 10; // 0..=10 harmonic class
    match band {
        0 => score += 20.0,                       // nearly full: dead space
        1 => score += 8.0,                        // 10-19: only tiny items fit
        2 | 3 => score -= 6.0,                    // 20-39: useful small fit
        4 | 5 => score -= 10.0,                   // 40-59: prime zone
        6 | 7 => score -= 4.0,                    // 60-79: moderate
        _ => {}                                   // 80+: near empty
    }

    // Modulo-arithmetic coupling: post_residual divisible by common item sizes (10/20/25/50)
    // is a "harmonic" residual likely to be perfectly filled later.
    if post_residual > 0 {
        let mut harm = 0.0;
        if post_residual % 10 == 0 { harm += 5.0; }
        if post_residual % 20 == 0 { harm += 4.0; }
        if post_residual % 25 == 0 { harm += 3.0; }
        if post_residual % 50 == 0 { harm += 3.0; }
        score -= harm * frac.max(0.1);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 20.0; // perfect pairing
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty scaled by how close it was
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it's chosen
    // only when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.5;
        // Opening a new bin early is fine if current item is large and would
        // leave a bad harmonic residual elsewhere.
        if item_size >= 50 {
            score -= 4.0;
        }
    }

    // Progress-aware tie-breaking: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * progress * 4.0;

    // Mean-residual coupling: if this bin is far below mean residual, it's an
    // outlier worth filling.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold the smallest
    // possible item (or the lookahead item) are essentially wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fill
    } else {
        // Dead space if nothing later can use it.
        let usable_by_next = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        let dead = 1.0 - usable_by_next;
        // Small gaps are worst: penalize proportionally to deadness and smallness.
        let gap_smallness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += dead * (10.0 + 40.0 * gap_smallness * gap_smallness);
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward strongly (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets penalized via its large residual being
    // offset by this term.
    if bin_residual == bin_capacity {
        score += 5.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins tighter than average (good fit relative to fleet).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Late in the stream, be slightly more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tiny post residual is excellent.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 120.0;
        } else if next_item_size as u32 <= post_residual {
            // next item fits after this placement: scale reward by closeness.
            score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize large leftover dead space.
            score += 0.25 * (post_residual as f64 - next_item_size as f64).max(0.0).min(60.0);
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of dead space.
    let pr = post_residual as f64;
    if pr > mean_residual + 15.0 {
        score += 0.5 * (pr - mean_residual);
    } else if pr < mean_residual - 15.0 {
        score -= 0.3 * (mean_residual - pr).min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless they fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if no open bin fits well, opening fresh can win via lookahead.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() <= 5 {
            score -= 60.0;
        }
    }

    // Mild penalty on bin proliferation early in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr * pr) / cap * 0.35;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // if next item would have fit better in a different bin, mild penalty.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (n / cap));
        } else {
            score += 6.0 * (n / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins are crowded
    // or the fit would be very poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        let poor_fit = (item_size as f64) / cap < 0.5;
        let mut new_bin_penalty = 25.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0; // forced open
        } else if crowded > 0.35 && poor_fit {
            new_bin_penalty -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 15.0 * progress;
        score += new_bin_penalty;
    }

    // Slight preference for fuller bins when many bins are open.
    score += (open_bins_count as f64) * 0.4;

    // Deviation from mean residual: prefer bins that are below-average residual (fuller).
    score += (mean_residual - bin_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = post_norm * (1.0 + 1.8 * progress * post_norm + 2.2 * progress * progress * (1.0 - post_norm));
    let mut score = poly * 100.0;

    // Reward tight fits smoothly (quartic decay of post-residual)
    score -= 45.0 * (1.0 - post_norm).powi(4) * fit_ratio;

    // Penalize dead space that next item likely can't use (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0) / cap;
        let usable = (nx / pr.max(1.0) as f64).min(1.0);
        score += 30.0 * gap * (1.0 - usable) * (0.5 + progress);
    }

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin residual deviates from mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: prefer opening new bins early, penalize late
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are more valuable (dead space minimized).
    let r = post_residual;
    let cls = r / 10; // integer-division threshold class (0..10)
    match cls {
        0 => score -= 40.0,             // post_residual < 10: nearly perfect fit
        1 => score -= 25.0,             // 10..19
        2 => score -= 12.0,             // 20..29
        3 => score -= 4.0,              // 30..39
        4 => score += 6.0,              // 40..49: awkward zone
        5 => score += 10.0,
        6 => score += 14.0,
        _ => {}                          // large leftovers are naturally penalized by base score
    }

    // Modulo-5 harmonic bonus: residues divisible by 5 pair well with
    // common item sizes (multiples of 5/10).
    if r % 5 == 0 && r > 0 {
        score -= 3.0;
    }
    if r % 10 == 0 && r > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward leftovers that can host the next item.
    if next_item_size > 0 {
        if r >= next_item_size {
            // post residual exactly matches next item -> excellent chaining
            if r == next_item_size {
                score -= 18.0;
            } else {
                let waste = (r - next_item_size) as f64;
                score -= 8.0 * (1.0 - waste / bin_capacity as f64);
            }
        } else {
            // leftover too small for the next item: penalize proportionally
            score += 6.0 * (next_item_size - r) as f64 / 50.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, mildly prefer tighter fits (implicit via base)
        score += 1.5 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // New-bin candidate: only attractive when open bins are congested
    // (mean residual small) or this bin would be the sole fit.
    if bin_residual == bin_capacity {
        let congestion = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 60.0 + 40.0 * congestion;
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            score -= 10.0; // big item followed by another big item: fresh bin is good
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins tighter than average.
    score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // creating a gap too small for next item
    }

    // Last chance: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Discourage bins far below mean residual (wasteful use of a roomy bin)
    // when item barely fits, i.e. tight fit in a nearly full bin is good.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * tightness * tightness;

    // New-bin candidate: only attractive if it enables a good future pairing.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 35.0; // pair fits together: opening a new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but with diminishing returns.
    score = 0.6 * score + 0.4 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // matches the next item's size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Strong bonus if next item fits exactly into the resulting residual.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize if the next item cannot fit in the post residual but could
        // have fit with a different placement choice (wasted lookahead).
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // already "junk" bins; dumping into them is cheap. Bins far above the
    // mean are precious; using them wastefully is penalized.
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.5 * (res - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if post_residual <= 10 {
            score -= 10.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when the item fits poorly everywhere else or the item
    // is large relative to typical residual.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.7 * bin_capacity as f64;
        let late_stream = step_index as f64 / (total_items.max(1) as f64) > 0.7;
        if poor_fit || late_stream || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 20.0; // discourage opening bins when good fits exist
        }
        // Large items deserve fresh bins to avoid fragmentation.
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize creating dead space that is hard to fill (small leftover).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer filling bins that are already relatively full (residual small).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * fill_ratio * fill_ratio;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or many bins are open with low mean residual (fragmented state).
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64; // post residual of new bin
        let fragmentation = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).min(1.0)
        } else {
            1.0
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so open bins usually win; reduced late in stream or when fit is poor elsewhere.
        let mut new_bin_penalty = 40.0 - 15.0 * progress;
        // If the item leaves tiny residual in a new bin, opening is fine (it will be nearly full).
        if tightness <= 10.0 {
            new_bin_penalty -= 30.0;
        }
        // If open bins are too empty relative to item, opening is more attractive.
        new_bin_penalty -= 10.0 * (1.0 - fragmentation);
        // Many open bins: discourage further proliferation.
        new_bin_penalty += (open_bins_count as f64).sqrt() * 2.0;
        score += new_bin_penalty.max(0.0);
    }

    // Mild tie-break: prefer bins with residual close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * progress * (1.0 - prn);
    score += 30.0 * poly;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - prn;
    score -= 25.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space below the smallest plausible item size.
    if pr < item_size as f64 {
        score += 15.0 * (1.0 - pr / cap);
    }

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual fits the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && next_item_size > post_residual as u32 && post_residual > 0 {
        score += 6.0 * (1.0 - prn);
    }

    // Slight aversion to proliferating bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    // New-bin candidate: neutral-ish baseline, discouraged when a decent fit exists.
    if bin_residual as f64 == cap {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse bands
    // using integer division on the capacity (quarters of the bin).
    let post_class = post_residual / (bin_capacity / 4).max(1); // 0..=4
    // Dead-space penalty grows super-linearly for large leftover classes
    // (leftovers > half a bin are wasteful unless a new bin is better).
    score += (post_class as f64) * (post_class as f64) * 2.0;

    // Tight fit reward: leftover in the smallest class is ideal.
    if post_class == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (harmonic chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_class = (post_residual - next_item_size) / (bin_capacity / 4).max(1);
        score -= 10.0 + 5.0 * (1.0 - next_class as f64 / 4.0);
    }
    // Penalize if next item is slightly too big for the leftover (near-miss trap).
    if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, favor it heavily
    // (avoid opening a new bin for a mediocre fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin's post_residual is large,
    // so the quadratic class penalty already raises its score. Give it a
    // mild structural bonus so it competes when open bins are fragmented,
    // but scale by how much room it leaves (small items -> keep score high).
    if bin_residual == bin_capacity {
        score -= 5.0;
        // If many open bins exist with scattered residuals, prefer fresh bin.
        if open_bins_count > 3 && mean_residual < post_residual as f64 {
            score -= 6.0;
        }
    }

    // Slight preference for bins below the mean residual (consolidating space).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10, the classic minimum item size,
    // here use a small threshold like < 8) are pure waste; large gaps are reusable.
    if post_residual < 8 {
        score += 60.0; // unusable dead space
    } else if post_residual < 15 {
        score += 25.0 * (15.0 - post_residual as f64) / 7.0; // risky gap
    } else {
        // Reward leaving a gap that can plausibly fit future items.
        score -= 6.0;
    }

    // Tight-fit bonus: reward exact or near-exact fills.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 18.0;
    } else if fill_ratio > 0.7 {
        score -= 9.0;
    }

    // Open-bin pressure: discourage spreading when many bins are already open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened and this residual is stranded.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins far from the mean residual
    // (below mean = tighter bin, good; above mean = loose bin, less urgent).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            score += 8.0; // next item can't use this gap
        }
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin moderately so tight fits win,
    // but not so much that terrible placements (tiny post_residual) win.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    }

    // Mild stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin closed by next item
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.35 * slack; // penalize leftover slack after chaining
        } else {
            // next item cannot fit here; slight penalty proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: strongly prefer minimal final residual.
        score += 10.0 * fit_ratio;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tight"; prefer using them.
    let rel = post_residual as f64 - mean_residual;
    score += 0.25 * rel;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless item is large relative to capacity
        let large = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 20.0 * large;
        // If many open bins, discourage spreading
        score += 0.5 * open_bins_count as f64;
    }

    // Early stream: be slightly conservative with tight fits to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 / (1.0 + tightness);

    // Penalize dead space: residuals too small to plausibly fit future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 60.0 * (1.0 - progress); // early dead space is more costly
    } else if post_residual < 20 {
        score += 20.0 * (1.0 - progress);
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward when the next item also fills this bin nicely.
        let post2 = post_residual - next_item_size;
        score -= 10.0 / (1.0 + post2 as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slightly neutral.
        score += 5.0;
    }

    // Last chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins: compare residual to the mean residual across open bins.
    score += (bin_residual as f64 - mean_residual) * 0.8;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: opening a new bin should only win when the
    // fit into existing bins is bad (large post residual or dead space).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 45.0;
        // Early in the stream, a fresh bin gives flexibility.
        score -= 30.0 * (1.0 - progress);
        // If the current bin would leave a large unusable remainder, a new
        // bin becomes attractive.
        if post_residual < 15 { score -= 40.0; }
        // Late in the stream, avoid opening bins unless necessary.
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) - norm_pr * (1.0 + 2.0 * progress);
    let mut score = pr + 20.0 * poly;

    // Penalize dead space relative to mean residual, smoothly
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - nx / cap) * (0.5 + progress);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for proliferation of open bins
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only for tight fits elsewhere
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by how reusable it is.
    // Residuals that are multiples of common item sizes (or large enough) are valuable.
    let pr = post_residual;
    let small_item = 10u32.min(bin_capacity);
    let harmonic_bonus: f64 = if pr == 0 {
        0.0
    } else if pr % 10 == 0 {
        // Residual aligned to the classic item grid: highly reusable.
        60.0
    } else if pr % 5 == 0 {
        30.0
    } else if pr >= 20 {
        10.0
    } else {
        // Tiny dead space (< 20) is nearly unusable: penalize hard.
        -80.0
    };
    score -= harmonic_bonus;

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0; // chain of perfect fits
        } else if next_item_size < pr {
            // Next item fits: residual class coupling.
            let slack = pr - next_item_size;
            if slack % 10 == 0 { score -= 80.0; } else if slack >= 10 { score -= 20.0; }
            else { score += 60.0; } // leaves dead space
        } else {
            // Next item won't fit here: residual becomes dead unless large enough.
            if pr < 10 { score += 120.0; }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a good (harmonic) fit, or when mean residual is already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (mean_residual % 10.0)) / bin_capacity as f64;
        let pressure = (open_bins_count as f64) / ((step_index as f64) + 1.0);
        // Base cost of a fresh bin, discounted when open bins are fragmented junk.
        score = 0.35 * bin_capacity as f64
            - 200.0 * fragmentation
            - 30.0 * pressure
            - (item_size as f64) * 0.5;
        if next_item_size > 0 && next_item_size % 10 == 0 {
            score -= 40.0; // fresh bin pairs well with grid-aligned next item
        }
    }

    // Mild progression term: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 25.0 * progress * ((bin_capacity - pr) as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that could still fit typical future items (>= 10).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: favor bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless the fit
    // into existing bins would be poor (large post_residual or dead space).
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: new bin is fine
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 12.0; // dead space for the known next item
    }

    // Late in the stream, tighten up: prefer exact fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match strongly
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        // Extra bonus for exact match
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize if post_residual cannot fit the next item (dead space risk)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny unusable slivers (below minimum item size 1..100 heuristic)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count > 0 {
            score += 15.0 * fitting_bins_count as f64;
        }
        // Late in stream, opening new bins is fine (no future waste concern)
        if total_items > 0 && (step_index as f64 / total_items as f64) > 0.9 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residual capacity usage
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: strongly favor bins that end with zero residual.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tight-fit reward: item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to typical item sizes.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < item_size as f64 {
        score += 4.0; // residual too small for average future items
    }
    score += 0.05 * (dead * dead / 100.0);

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted space
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing ones.
    let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += 0.5 * crowding;

    // Time horizon: early in the stream, be more selective (penalize mediocre fits);
    // late in the stream, just pack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * fill_ratio * 5.0;

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64 * 1.1;
        if good_fit_exists {
            score += 40.0; // keep using existing bins
        } else if fitting_bins_count == 1 {
            score += 10.0; // existing bin is a last chance; slightly discourage new bin
        } else {
            score -= 2.0; // no decent fit anywhere; allow new bin
        }
        // Late in the stream, prefer closing out with existing bins.
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Polynomial coupling: dead space penalized more as stream progresses
    let dead = pr / cap;
    score += dead * dead * (1.0 + 6.0 * progress) * cap * 0.1;

    // Tight fit reward (smooth, quadratic in item fraction)
    let frac = item_size as f64 / cap;
    score -= 4.0 * frac * (1.0 - frac) * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 4.0 * progress;
    }

    // Lookahead: penalize wasting space needed by next item
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 0.5 * gap * (0.5 + progress);
        } else {
            score -= 0.3 * (-gap) * (1.0 - progress);
        }
    }

    // New-bin candidate: encourage when open bins are crowded, discourage early
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 2.0 + 8.0 * (1.0 - crowd) * (1.0 - progress);
        score -= 2.0 * mean_residual / cap;
    }

    // Mild preference for filling bins closer to mean residual
    score += 0.2 * (pr as f64 - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are preferred (tight fits).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Penalize residuals in dead-space classes (residues that few item sizes can use).
    // Items are 1..=100; a residual r is "usable" if some plausible item <= r exists.
    // Classify by integer division thresholds.
    let dead_penalty = if post_residual == 0 {
        -50.0 // perfect fit is ideal
    } else if post_residual < 10 {
        60.0 // tiny residue, almost unusable dead space
    } else if post_residual < 25 {
        10.0
    } else if post_residual < 50 {
        0.0
    } else {
        -5.0 // large residual keeps flexibility
    };
    score += dead_penalty;

    // Modulo-arithmetic harmony: reward when post_residual shares a divisor
    // structure with common item sizes (residue class alignment).
    let pr = post_residual;
    let harmony = ((pr % 10 == 0) as i32) * 6
        + ((pr % 5 == 0) as i32) * 3
        + ((pr % 25 == 0) as i32) * 4;
    score -= harmony as f64;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            score -= 15.0 * (1.0 - next_post as f64 / cap);
        } else {
            // next item won't fit here; mildly penalize very tight leftovers
            score += 8.0 * frac;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 60 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when no open bin gives a decent fit (high mean residual
    // fragmentation or the item is large relative to best open space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Cost of a fresh bin rises as the stream progresses.
        let fresh_cost = 70.0 + 40.0 * progress + 3.0 * open_bins_count as f64;
        score += fresh_cost;
        // But if the item is huge and mean residual is small, opening is fine.
        let big_item = item_size as f64 > 0.6 * cap;
        if big_item && mean_residual < item_size as f64 {
            score -= 90.0;
        }
    }

    // Mild preference for consolidating into bins below the mean residual
    // (pack into emptier bins to consolidate waste).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight global pressure: more open bins -> prefer tighter packing.
    score += 0.5 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fills relative to residual (small waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Penalize wasting a large residual on a small item (poor pairing).
    if post_residual > 50 {
        score += 12.0;
    }

    // Open-bin pressure: encourage consolidating into existing bins.
    score += 3.0 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual, reward leaving it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * next_item_size as f64;
        } else {
            score += 5.0;
        }
    }

    // Prefer bins below mean residual (keeps residual spread balanced).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let gap = pr - nr;
            if gap == 0.0 {
                score -= 40.0; // perfect chain fit
            } else if gap <= 10.0 {
                score -= 20.0 * (1.0 - gap / 10.0);
            } else {
                // penalize leaving space that next item cannot use well
                score += (gap / 100.0) * 8.0;
            }
        } else {
            // next item does not fit in residual: dead space risk
            score += (nr - pr).min(30.0) * 0.4;
        }
    }

    // Penalize bins far from mean residual (prefer balanced usage) unless last-chance.
    if fitting_bins_count > 1 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    } else if fitting_bins_count == 1 {
        score -= 25.0; // last chance before new bin: strongly favor using it
    }

    // New-bin candidate: keep it attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 + 30.0 * tightness;
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Late stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    // Many open bins: mild pressure to fill existing ones.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: post_residual dominates, add a quadratic penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item can still fit here: mild reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // Next item won't fit after this placement: penalize large post_residual waste.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item of the stream: closing bins tightly is all that matters.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with below-average residual (keep big holes for future big items).
    let res_diff = bin_residual as f64 - mean_residual;
    score += 0.05 * res_diff;

    // Early in the stream, be slightly conservative about fragmenting bins
    // (more future items => residual value is higher).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    score += (1.0 - progress) * 0.10 * post_residual as f64;

    // If many bins are open, consolidation is valuable; penalize spreading.
    if open_bins_count > 4 {
        score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin should only win when the item is large
    // and would leave a poor fit elsewhere; make the empty bin moderately attractive
    // for big items but not for small ones.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * item_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: waste after placement, softly normalized
    let mut score = norm_pr;

    // Quadratic penalty on large dead space (smooth non-linear coupling)
    score += 0.8 * norm_pr * norm_pr;

    // Stream-progress coupling: later in the stream, waste matters more
    score += 0.6 * norm_pr * progress;

    // Reward tight fits (small post_residual) with smooth saturation
    score -= 0.5 * (1.0 - norm_pr).powi(3);

    // Lookahead: bonus if next item fits in the post residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (nx <= pr) as f64;
        let tight_next = 1.0 - ((pr - nx).abs() / cap);
        score -= 0.4 * fits_next * tight_next.max(0.0);
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 1.5;
    }

    // Penalize opening a new bin when good alternatives exist (scaled by progress)
    score += is_new_bin * (0.7 + 0.5 * progress);

    // Mild pressure to prefer bins below mean residual (balancing open bins)
    score += 0.2 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Perfect fit: strongest reward (harmonic class 0) ---
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Dead space penalty: residuals below the minimum item size (10) are nearly unusable ---
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // --- Harmonic class logic: penalize residuals whose modulo class makes them awkward ---
    // Residuals congruent to small values mod 10 pair poorly with future items.
    score += (post_residual % 10) as f64 * 0.6;
    // Residuals in the "just above half" band (51..=60) tend to trap medium items poorly.
    if post_residual > 50 && post_residual <= 60 {
        score += 8.0;
    }

    // --- Lookahead (k=2) coupling ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // This bin becomes a perfect fit for the next item: excellent.
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after placement.
            score -= 15.0;
        } else if next_item_size <= bin_residual {
            // Placement blocks the next item that currently fits: penalize.
            score += 25.0;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin while others fit the item.
        score += 40.0;
        if fitting_bins_count == 0 {
            // No open bin can fit: must open a new bin.
            score = -500.0;
        }
        // If the next item is at least as large, reserving fresh capacity is attractive.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    } else {
        // Prefer filling existing bins more as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // Slight pull toward bins below the mean residual (consolidate fullness).
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) after placement are useless
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual relative to capacity)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 25.0;

    // Perfect fill is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would fit better in a fresh bin, penalize wasting this bin's space
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, reduced when existing bins are fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 40.0 - fragmentation.min(40.0);
        // early in stream, new bins are cheaper; late, expensive
        score += progress * 30.0;
    }

    // Slight preference for bins below mean residual (balance load)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space that cannot fit the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 + (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward bins whose leftover exactly serves the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Prefer tight fits: small post_residual relative to mean residual.
    let tightness = post_residual as f64 / (mean_residual.max(1.0));
    score -= 8.0 * (1.0 - tightness.min(1.5));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins fit well.
    if bin_residual == bin_capacity {
        score += 20.0 + post_residual as f64 * 0.3;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Late in stream, be greedier about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving large unusable residue.
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening a new bin when other bins fit, scaled by global slack.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 + 30.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.5;
        // Many open bins: discourage further proliferation.
        score += open_bins_count as f64 * 2.0;
    } else {
        // Slight preference for bins with less residual diversity from the mean.
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Early stream: tolerate moderate residuals; late stream: penalize waste more
    let progress_penalty = pr_norm * (0.5 + 1.5 * p2 + 2.0 * p3);
    score += progress_penalty * cap * 0.5;

    // Smooth quadratic coupling: small post-residuals are valuable (tight fits)
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * cap * 0.6;

    // Smooth cubic interaction between post_residual and mean residual:
    // prefer bins whose residual deviates usefully from the mean
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * cap * 0.3;
    score -= dev * dev * dev * cap * 0.2;

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns) / cap;
        let k = (-gap * gap * 8.0).exp();
        score -= k * cap * 0.35;
    }

    // Last-chance bonus (smooth sigmoid on fitting_bins_count)
    let scarcity = 1.0 / (fitting_bins_count as f64);
    let sig = 1.0 / (1.0 + (-6.0 * (scarcity - 0.5)).exp());
    score -= sig * cap * 0.4;

    // Mild penalty for bin proliferation (smooth saturation)
    let ob = open_bins_count as f64;
    score += (ob / (ob + 5.0)) * cap * 0.15;

    // Encourage filling bins deeply as stream progresses (smooth term)
    score -= (item_size as f64 / cap) * cap * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity quarters.
    let quarter = bin_capacity / 4;
    let residue_class = (post_residual % quarter) as f64;
    score += residue_class * 0.35; // prefer residuals landing on harmonic boundaries (multiples of 25)

    // Reward tight fits: post_residual small relative to capacity
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < quarter {
        score -= 10.0;
    }

    // Penalize dead space that cannot hold the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward leaving room exactly sized for next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing bins would leave large dead space
    if bin_residual == bin_capacity {
        let best_existing = (post_residual as f64) + residue_class * 0.35;
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin if open bins are nearly full on average
        score = 40.0 + pressure * 60.0 - best_existing * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance).
    // A residual is "dead" if it is too small to fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Gradient penalty: residuals just above the minimum item size are fragile.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect-fit lookahead: if the next item exactly matches post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    }
    // If next item fits post_residual, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item cannot fit, the residual is likely to linger: penalize.
    else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but allow opening new bins when few are open (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Deviation from mean residual: prefer bins that are tighter than average.
    score += (mean_residual - bin_residual as f64).abs() * 0.3;
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // New-bin candidate: give it a mild baseline so it loses to good fits
    // but wins over bad fits (large post_residual on existing bins).
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: reward tight residual match
            score -= 0.5 * ((post_residual - next_item_size) as f64).abs().min(50.0);
        } else {
            // next item won't fit here: penalize small dead space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge
    if bin_residual == bin_capacity {
        score += 50.0 + 0.5 * item_size as f64;
        if item_size >= 80 {
            score -= 150.0;
        }
    }

    // Penalize leaving residual far below mean residual (wasteful small gaps)
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Tight fit reward relative to residual
    score -= 0.3 * (item_size as f64 / bin_residual.max(1) as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: mild penalty for stranding space.
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure tight-fit greed, no future to plan for.
        score -= 10.0 * tightness;
    }

    // Prefer using fuller bins relative to the fleet average (best-fit style balancing).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Early in the stream, be more willing to spread items (keep flexible residuals);
    // late in the stream, consolidate aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage opening yet another bin; new empty bins get a penalty
    // unless they are truly needed (handled by the fitting_bins_count bonus above).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: post_residual scaled by smooth progress-dependent decay.
    let decay = 1.0 + 0.8 * progress * progress;
    let mut score = post * decay;

    // Non-linear coupling: reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space non-linearly.
    let dead = post / cap;
    score += 20.0 * dead * dead * dead;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > post_residual {
        score += 4.0 * (1.0 - post / cap);
    }

    // Smooth interaction between item fraction and mean residual crowding.
    let crowd = mean_residual / cap;
    score += 3.0 * fit * (crowd - 0.5) * (crowd - 0.5) * 4.0;

    // Mild preference for consolidating into fewer bins early on.
    score += 0.3 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: penalize slightly unless existing bins are crowded.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap;

    // Penalize dead space in awkward residue classes: small but unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // sliver: nearly dead space
    }
    // Modulo-10 classes: residuals that are multiples of 10 are more reusable
    let mod10 = post_residual % 10;
    score += (mod10 as f64) * 1.5;

    // Reward residuals that can fit "typical" item classes (integer division thresholds)
    if post_residual >= 80 { score -= 8.0; }
    else if post_residual >= 50 { score -= 4.0; }
    else if post_residual >= 30 { score -= 1.0; }
    else { score += 6.0; } // small residuals less flexible

    // Lookahead coupling: does this bin remain useful for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // exact-class match: post_residual exactly equals next size class
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish, slightly penalize early opening
    if bin_residual == bin_capacity {
        score += 15.0;
        // late in stream, opening new bins is more acceptable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        // if next item is large, fresh bin is attractive
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Prefer bins below mean residual (tighter bins get filled first)
    score -= (mean_residual - pr) * 0.3;

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (perfect fill strongly favored).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 + progress) * 0.8;

    // Prefer bins below mean residual (tighter bins first) to keep large gaps open.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. penalize opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { -5.0 } else { 15.0 };
        score += escape + (bin_capacity as f64) * 0.5;
    }

    // Lookahead: if next item could use the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item (or close to it).
            let match_gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - match_gap / (bin_capacity as f64));
        } else {
            // Next item cannot follow here; penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.35 * shortfall;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 8.0 * tightness;
    }

    // Relative to mean residual: bins tighter than average are precious, use them.
    if (post_residual as f64) < mean_residual {
        score -= 0.4 * (mean_residual - post_residual as f64);
    } else {
        score += 0.25 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // and would leave a very usable residual, or no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Large items pair well with a fresh bin (full lookahead chain possible).
        if item_size >= bin_capacity / 2 {
            score -= 18.0;
        }
        // If next item chains perfectly behind this one in a fresh bin, allow opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; small dead-space penalty for very small leftovers.
            if post_residual < 10 {
                score += 12.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid wasting it on a bad fit,
    // but prefer it over opening a new bin when the fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate, favor existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + 0.5 * progress);
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // New-bin candidate: penalize opening a new bin, more so early and for small items.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            penalty = 0.0; // no alternative
        }
        score += penalty * (1.0 - 0.3 * progress);
    }

    // Penalize leaving awkward residuals (odd small gaps) in mid-stream.
    if post_residual > 0 && post_residual < 10 && progress < 0.95 {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Tight fits are strongly favored: smooth quadratic decay of reward as post_residual grows
    let tight = (pr / cap).powi(2);
    score -= 60.0 * (1.0 - tight);

    // Non-linear coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize very small residuals);
    // later, filling tightly matters more.
    let flex_penalty = (pr / cap) * (1.0 - progress) * (pr / cap) * cap * 0.5;
    score += flex_penalty;

    // Penalize bins far from mean residual unless the fit is tight (smooth interaction)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - (pr / cap));

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - (pr / cap).powi(3));
    }

    // Lookahead: reward if next item fits the post-residual (smooth exponential match)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0);
    }

    // Mild penalty for scattering across many open bins, growing with progress
    score += open_bins_count as f64 * progress * 0.5;

    // New-bin candidate: make it moderately attractive only when no tight fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // New-bin candidate: strongly penalize by default so it only wins when
    // no open bin is acceptable (or none fits at all).
    if bin_residual == bin_capacity {
        let mut nb = cap + 5.0;
        if fitting_bins_count == 0 {
            nb -= cap; // forced open: no open bin can hold the item
        }
        return nb;
    }

    // Progress fraction: later in the stream, consolidation matters more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals of 1..9 are nearly unusable (min item 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 + 4.0 * t;
    }

    // Harmonic class reward: residuals on multiples of 10 remain "usable slots"
    // for any item size class; keep the bin on-grid.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Lookahead (k=2): reward bins that can also host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 {
            // penalize blocking the next item proportionally to the gap
            score += 2.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (score must beat the new-bin candidate).
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Mild pressure toward bins below the mean residual (balance filling).
    score += 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: reward using up space (tight fits preferred).
    score += (bin_capacity - post_residual) as f64 * -1.0;

    // Strict dead-space avoidance: small leftover gaps are poison.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Minimum realistic item size zone: gaps below ~10 are dead space.
        if pr < 10.0 {
            score += 500.0 * (10.0 - pr) / 10.0;
        } else if pr < 20.0 {
            // Semi-dead zone: only very small items (1..=9) can use it.
            score += 120.0 * (20.0 - pr) / 20.0;
        } else if pr < 35.0 {
            // Awkward zone: unusable by mid/large items.
            score += 25.0 * (35.0 - pr) / 35.0;
        }
    } else {
        // Perfect fill is heavily rewarded.
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Penalize leaving a gap the next item cannot close well.
            score += gap * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this bin's
    // post-residual would be truly dead space.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin.
        score += 60.0;
        // Opening a new bin is expensive when few bins are open (consolidation phase).
        score += open_bins_count as f64 * 8.0;
        // Late in the stream, prefer filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 80.0;
    } else {
        // Open-bin pressure: mildly discourage scattering across many bins.
        score += open_bins_count as f64 * 1.5;
    }

    // Mean-residual coupling: if this bin is far below mean residual,
    // filling it is valuable (it's the most constrained bin).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 1.2;
    } else {
        score += (-dev) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving dead space that the next item cannot use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            score += 4.0 + (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins whose residual deviates below the mean (tighter bins get filled)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 3.0; // new bin is fine if it perfectly serves next item too
        } else {
            score += 10.0;
        }
        score += 0.5 * open_bins_count as f64;
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless the fit in open bins is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0;
        // Late in the stream, opening new bins is more acceptable (fewer future items to waste space for).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * progress;
    }

    // Reward tight fits (small post_residual already does this; amplify the sweet spot).
    if !is_new_bin {
        if post_residual <= 5 {
            score -= 25.0;
        } else if post_residual <= 15 {
            score -= 12.0;
        }
        // Penalize leaving dead space that no plausible item can use.
        if post_residual > 0 && post_residual < 10 {
            score += 0.0; // already rewarded above
        }
        if post_residual > 40 {
            score += (post_residual as f64 - 40.0) * 0.6;
        }
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    if open_bins_count > 4 && !is_new_bin {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Mean residual context: if the average residual is large, tight packing matters less.
    score += 0.05 * mean_residual;

    // Time horizon: early items should keep bins flexible (favor larger post_residual slightly),
    // late items should fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.1 * post_residual as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Normalized post-residual and its smooth polynomial coupling with progress
    let r = post / cap;
    let r2 = r * r;
    let r3 = r2 * r;
    let p = progress;
    let p2 = p * p;

    // Base: waste after placement, modulated non-linearly by stream progress.
    // Early on (p small) large residuals are fine; late (p large) waste is penalized more.
    let mut score = post * (1.0 + 0.8 * p2) - 12.0 * r2 * (1.0 - p) + 20.0 * r3 * p;

    // Tight fit reward: quadratic bonus that grows as post_residual shrinks
    let fit_quality = 1.0 - r;
    score -= 18.0 * fit_quality * fit_quality * (0.5 + p);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 15.0 * p;
    }

    // Penalize bins whose residual deviates from the mean (fragmentation pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead coupling: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let n = (next_item_size as f64 / cap).clamp(0.0, 1.0);
        let gap = r - n;
        score -= 10.0 * (1.0 - gap * gap); // best when residual just covers next item
        score += 8.0 * gap * gap * p;      // excess slack penalized more later
    }

    // New-bin candidate handling: neutral baseline, mildly discouraged early,
    // acceptable late or when open bins are crowded.
    if is_new_bin {
        let crowding = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score = 0.5 * cap * (1.0 - p) + 30.0 * (1.0 - crowding) - 20.0 * p;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    } else if fitting_bins_count == 0 {
        score += 100.0; // shouldn't happen but guard
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (divisible by common item sizes) are more valuable to keep.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are harmonic with typical item sizes.
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 4.0; }

        // Dead-space penalty for tiny residuals (unusable slivers).
        if pr < 10 { score += 60.0; }
        else if pr < 20 { score += 25.0; }
    } else {
        // Perfect fit is excellent.
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            // Fractional coupling: how well does the next item divide the space?
            let fill = next_item_size as f64 / pr as f64;
            score -= 20.0 * fill;
            if pr % next_item_size == 0 { score -= 10.0; }
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers.
            score += 0.1 * (pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current
    // bins are very full / item is large relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If open bins are quite full on average, a new bin is fine.
        score = 40.0 + 50.0 * (1.0 - pressure);
        if item_size > 50 { score -= 15.0; }
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Prefer tighter bins: relative tightness of the fit.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky too; penalize quadratically as gap shrinks.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 1.5;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // next item can't use this gap; mild penalty scaled by waste
            score += (post_residual as f64) * 0.3;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 8.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: add pressure so it's chosen only when open bins are bad.
        score += 25.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: if the next item exactly fills post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // next item fits here too: reward proportional closeness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit in the leftover: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 10.0 + dead * 0.3;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin early in the stream unless necessary.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual is better, with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap.
            score += 0.3 * (post_residual as f64 - (next_item_size as f64)) * 0.1;
        }
    }

    // Prefer bins with residual below mean residual (tighter bins first),
    // keeping looser bins available for larger future items.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate: prefer using existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses and as
        // more bins are already open.
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // Opening a new bin is acceptable if current bins fit poorly.
        if fitting_bins_count >= 1 && (bin_residual as f64 - item_size as f64) < (post_residual as f64) {
            score -= 5.0;
        }
    }

    // Mild penalty for very many open bins to encourage consolidation.
    score += 0.1 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual

    // Non-linear polynomial coupling of post-residual with stream progress
    let base = x * (1.0 + 0.6 * progress) - 1.4 * x * x * (1.0 - progress) + 0.8 * x.powi(3);

    // Penalty for dead space too small for typical items
    let dead = if pr > 0 { (1.0 - pr / (pr + item_size as f64)) * 3.0 } else { 0.0 };

    // Lookahead: reward residual that can host next item
    let look = if next_item_size > 0 {
        if post_residual >= next_item_size { -1.2 } else { 0.5 * (next_item_size as f64 / cap) }
    } else { 0.0 };

    // Last chance bin before opening a new one
    let last = if fitting_bins_count == 1 { -2.0 } else { 0.0 };

    // Mild preference for tighter-than-average bins
    let tight = (mean_residual - bin_residual as f64) * 0.02;

    let mut score = base * 10.0 + dead + look + last + tight;
    // New-bin candidate: keep neutral-ish, slightly discouraged early
    if bin_residual == bin_capacity {
        score += 1.5 - 2.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into octiles
    let oct = (bin_capacity / 8).max(1);
    let class = post_residual / oct;

    // Reward near-perfect fits strongly (post_residual in lowest octile classes)
    match class {
        0 => score -= 40.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 5.0,
        _ => {}
    }

    // Penalize dead space that no future item can plausibly use:
    // post_residual below the minimum item size (1..=100 unknown, assume small)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Modulo coupling: does next_item_size fit into post_residual exactly / nicely?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits here: reward, more if snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack.min(18.0);
            if post_residual % next_item_size == 0 {
                score -= 10.0; // perfect modular split
            }
        } else {
            // lookahead won't fit here; penalize if we also create a bad remainder
            score += 8.0;
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // prefer tightest among many; post_residual already handles this,
        // but add mild penalty for spreading across many fitting bins
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate handling: empty bin has residual == capacity
    if bin_residual == bin_capacity {
        // Opening a new bin is good only late in the stream or when nothing fits well
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let base = 60.0; // default cost of a fresh bin
        // early stream: slightly discourage new bins; late stream: neutral
        score = base - 15.0 * (1.0 - progress) + post_residual as f64;
        // if next item is huge, a fresh bin is attractive
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a straggler —
    // prefer filling stragglers to consolidate open bins
    if mean_residual > 0.0 {
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score -= dev.min(20.0) * 0.8;
        } else {
            score += (-dev).min(20.0) * 0.4;
        }
    }

    // Integer-division threshold on post_residual: quarters of capacity
    let q = bin_capacity / 4;
    if post_residual > 3 * q {
        score += 6.0; // leaving more than 3/4 empty is wasteful when a smaller fit exists
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly unusable
    // for future items (min size 1, but practically small gaps waste space).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Moderate gaps (11..=25): mildly wasteful but still usable.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes less attractive.
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by open-bin pressure,
        // but allow it when this bin would otherwise create tiny dead space.
        score += 25.0 + 10.0 * pressure;
        if post_residual <= 10 && post_residual > 0 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward slightly with pressure so consolidation wins.
        score -= 2.0 * pressure;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item would NOT fit in post_residual, dead space is confirmed
    // for the next step; penalize proportionally.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: bins far below mean residual are "loose";
    // prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Progress: later in the stream, waste matters more (fewer chances to fix).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact fits
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        if post_residual as f64 >= look {
            let gap = post_residual as f64 - look;
            if gap == 0.0 {
                score -= 500.0; // perfect 2-chain
            } else {
                score -= 200.0 / (1.0 + gap);
            }
        } else {
            // next item cannot follow here; penalize wasted residual
            score += 0.5 * (look - post_residual as f64);
        }
    }

    // Penalize small dead space relative to the smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 40.0 * open_bins_count as f64;
    }

    // Late in stream, be more conservative (prefer filling existing bins)
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that cannot fit even the smallest future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual; mild penalty proportional to leftover
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty to keep new bins as fallback; relax over time if many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 15.0 * progress;
        // If mean residual across open bins is small (all bins nearly full), opening is fine.
        score -= (mean_residual / 10.0).min(30.0);
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    if open_bins_count > 3 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild penalty for very loose fits scaled by item size.
    score += 0.1 * (post_residual as f64 / (item_size.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: quadratic penalty on wasted space (dead space grows quadratically in badness)
    let mut score = pr + 0.35 * (pr / cap) * pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; late, demand tight fits.
    let prog_term = (pr / cap) * (pr / cap) * (0.5 + 1.5 * progress * progress);
    score += 40.0 * prog_term;

    // Cubic interaction: residual^3 normalized, scaled by openness of the system
    let open_norm = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * (pr / cap).powi(3) * (1.0 + open_norm);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = 1.0 - ((pr - nxt).abs() / cap);
        score -= 12.0 * compat.max(0.0) * (0.5 + 0.5 * progress);
        // penalize leaving a sliver just below the next item's size
        if pr < nxt && pr > 0.0 {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Mild preference for bins tighter than the mean residual (fragmentation control)
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: neutral-ish baseline with slight progress-aware bias
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - (if fitting_bins_count <= 1 { 30.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 25.0;
    }

    // Reward using bins that would otherwise leave awkward gaps.
    if post_residual > 0 && post_residual < item_size {
        score += 5.0; // gap smaller than item is nearly dead space
    }

    // Open-bin pressure: discourage spreading across many bins when tight fits exist.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // next item won't fit -> residual likely wasted
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) to consolidate.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make empty bin mildly attractive only when it beats bad fits;
    // base cost of opening a bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no good fit exists (many bins yet large post residuals would be wasted),
        // the empty-bin penalty is softened by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // 2-step lookahead: reward if next item fits exactly / well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: huge reward
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits; reward proportionally to how well it fills remainder
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * chain_fill;
        } else {
            // Next item won't fit here; penalize dead space left behind
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 15.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    } else {
        // Last item: just minimize post_residual (already base score)
        score -= 10.0;
    }

    // Relative to mean residual: bins tighter than average are better targets
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        // Penalize opening new bins early; slight relaxation late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base_penalty = 45.0 - 15.0 * progress;
        // If next item is large and current item leaves big residual elsewhere, opening may be fine
        score += base_penalty;
        if next_item_size > 0 && next_item_size <= 10 {
            score += 5.0; // tiny next item: keep residual space? no, open bins fine
            score -= 5.0;
        }
        // Opening a new bin is good if item is huge and would leave unusable slivers in open bins
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Penalize creating very small unusable residuals (dead space) unless chained
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer filling bins with many open bins (reduce bin proliferation)
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would not fit even in a fresh bin context, penalize
    // wasting near-perfect residual on the current item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 12.0;
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Global state coupling: many open bins with high mean residual ->
    // discourage opening new bins (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = (mean_residual / bin_capacity as f64) * (1.0 - progress) * 20.0
        + (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are spacious.
        score += new_bin_bonus;
        // But late in the stream, prefer fresh bins to consolidate large items.
        score -= progress * 10.0;
    }

    // Slight preference for filling fuller bins as stream progresses.
    score += (bin_residual as f64 / bin_capacity as f64) * progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1)

    // Base: minimize wasted space, with non-linear (quadratic/cubic) shaping
    let mut score = post + cap * pr * pr;

    // Smooth interaction: residual tightness coupled with stream progress.
    // Late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - pr;
    score -= cap * 0.6 * tightness * tightness * (0.5 + progress);

    // Penalty when post residual is a "dead zone": too small for likely next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 4.0 * (nxt - post) * (0.4 + 0.6 * progress);
        } else {
            // Reward leaving room exactly for the next item (smooth, non-linear)
            let fit_gap = (post - nxt) / cap;
            score -= 6.0 * (-8.0 * fit_gap * fit_gap).exp();
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    } else if fitting_bins_count > 1 {
        // mild competition bonus scaled non-linearly
        score -= 1.5 * ((fitting_bins_count - 1) as f64).ln().max(0.0);
    }

    // Encourage balancing against mean residual (smooth coupling)
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for proliferating bins as stream advances
    score += 0.3 * (open_bins_count as f64).ln() * (0.5 + progress);

    // New-bin candidate: make it attractive only when item fits poorly everywhere
    // (handled implicitly: an empty bin has post_residual = cap - item, which is
    // large, so it naturally loses unless dead-space penalties dominate elsewhere).
    if bin_residual == bin_capacity {
        score += 2.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Dead-space penalty: small unusable leftovers are bad unless tiny (perfect fit)
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else if post_residual <= 10 {
        score -= 15.0; // near-perfect fit
    } else if frac < 0.2 {
        score += 25.0; // unusable sliver
    }

    // Harmonic class via integer division of post_residual into buckets of 20
    let class = (post_residual / 20) as f64;
    score += class * 6.0;

    // Modulo structure: leftover congruent to common item sizes (e.g. multiples of 10)
    // is more likely to be filled by future items -> reward
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.15 * slack;
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers less
            score += 0.05 * (next_item_size as f64 - pr).max(0.0);
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the fit here is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, discounted when many bins are open
        score += 55.0 - 1.5 * (open_bins_count as f64).sqrt() * 4.0;
        // Late in the stream, avoid opening new bins more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If item is huge relative to capacity, new bin is fine
        if item_size as f64 > 0.7 * cap {
            score -= 25.0;
        }
    }

    // Prefer filling bins below the mean residual (balance / tight packing)
    score -= 0.3 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless the fit is good.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        // Dead space relative to the next item.
        score += 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from the mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step chain: post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0;
        } else {
            // penalize mismatch relative to next item size
            score += (diff as f64) * 0.35;
        }
        // reward if next item fits into post residual at all
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space unusable by next item
            score += (post_residual as f64) * 0.25;
        }
    }

    // Favor tight fits: small post residual overall
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Relative to mean residual: placing into a tighter-than-average bin is good
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin can chain with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward bins whose current residual is large relative to the item (good absorption)
    score -= 0.4 * (item_size as f64 / cap) * bin_residual as f64;

    // Lookahead: strongly favor placements where the next item still fits afterwards
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0;
        } else {
            // penalize creating dead space the next item cannot use
            score += 2.5 * post_residual as f64 / cap;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless the stream is young
    // and many future items are expected (horizon-aware exploration)
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let horizon_bonus = (1.0 - t) * 8.0;
        score += 12.0 + 0.15 * open_bins_count as f64 - horizon_bonus;
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score += 4.0; // fresh bin still leaves room for the next item
        }
    }

    // Global-state coupling: prefer bins whose post-residual is close to the mean residual
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize residual that is too small to be useful
    // (dead space) more aggressively as the stream progresses.
    let deadness = (1.0 - norm_pr).powi(3);
    score += 12.0 * deadness * (0.3 + 0.7 * progress);

    // Reward leaving space that exactly fits the next item (smooth bell around match)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= 20.0 * (-8.0 * diff * diff).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty relative to mean residual: avoid fragmenting bins that are
    // already much fuller than average (prefer filling emptier bins evenly).
    score += 0.15 * (mean_residual - pr);

    // Slight preference for keeping fewer open bins late in the stream
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Smooth new-bin discouragement: empty bin candidate gets a progress-dependent
    // penalty so we only open new bins when residuals are genuinely bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: classify leftover space by
    // capacity fraction (integer-division thresholds).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Dead space classes: small leftovers are "usable" only for tiny items.
    if post_residual > 0 && post_residual < sixteenth {
        // Nearly-dead sliver: strongly penalize unless it's a perfect fit (handled above).
        score += 40.0;
    } else if post_residual < eighth {
        score += 15.0;
    } else if post_residual < quarter {
        score += 4.0;
    } else {
        // Large leftover: bin remains flexible; mild reward.
        score -= 3.0;
    }

    // Harmonic compatibility: does the NEXT item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: leftover matches the next demand exactly or well.
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 120.0; // two-item exact closure
            } else if slack < sixteenth {
                score -= 30.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this leftover -> dead space risk.
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (item_size as f64) * 0.2;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give it a neutral-but-not-winning default.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = (bin_capacity / 2) as f64;
        // Attractive when open bins are crowded or item is large.
        let crowd = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score -= crowd * 0.5;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, consolidating is cheaper than sprawling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
        // If next item is big, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Modulo tie-breaker on post_residual: prefer leftovers in "nice"
    // residue classes (multiples of 5 / 10) which pair well with
    // decimal-ish item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    // Mild global pressure: when many bins are open, favor consolidation.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Mid-range dead space (10..20) is mildly penalized since few items fit.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 8.0; // dead space for the known next item
        } else {
            score += (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer spreading across fewer bins when residuals are ample.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residual close to mean (balanced packing) slightly.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early stream: keep bins flexible (avoid fragmenting too soon).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += post_residual as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base term.

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.5;

        // Perfect 2-chain bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If next item can't fit anywhere else after this placement, penalize wasting the slot.
        if post_residual < next_item_size && post_residual > 0 {
            score += post_residual as f64 * 0.3;
        }
    }

    // Penalize dead space that nothing (min size 1) can still use well —
    // scale by how far post_residual is below typical item sizes.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins tighter than average (good fits),
    // penalize bins that are looser than average (wasteful).
    score += (post_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: make empty bins mildly unattractive unless open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item is large and current item is small, a fresh bin may be better.
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
    }

    // Early in the stream, allow more bins; late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space if next item can't use it
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 0.5 * next_item_size as f64 * (0.5 + t);
        } else {
            score -= 0.35 * next_item_size as f64;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Many fitting bins: prefer fullest (post_residual already does), add mild penalty for spread
    score += 0.25 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        score = 0.6 * bin_capacity as f64 * (1.0 - pressure) + (1.0 - pressure) * (item_size as f64) + 25.0 * pressure * (1.0 - t);
        if fitting_bins_count == 0 { score -= 20.0; }
    }

    // Late stream: consolidate, penalize spreading across many bins
    score += t * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: tight fits rewarded via non-linear polynomial in post_residual
    let mut score = norm_post * norm_post * (3.0 - 2.0 * norm_post); // smoothstep: small post_residual favored
    score *= cap;

    // Coupling with stream progress: early stream tolerates loose fits, late stream punishes them
    let progress_coupling = 1.0 + progress * progress * 2.0;
    score *= progress_coupling;

    // Interaction: post_residual vs mean_residual deviation (smooth quadratic)
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Reward bins that are the last chance to fit
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_post);
    }

    // Lookahead: bonus if next item fits the post residual (smooth interaction)
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            score -= 3.0 * (1.0 - fits_next) * (1.0 - progress);
        } else {
            score += 1.5 * (-fits_next) * (0.5 + progress);
        }
    }

    // Mild penalty for too many open bins relative to stream length
    let bin_pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 10.0 * bin_pressure * norm_post;

    // Slight preference to fill larger items into fuller bins (item coupling)
    score -= 0.05 * (item_size as f64 / cap) * (cap - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // more "usable" by typical item sizes, so reward small harmonic distance.
    let residue_class = post_residual % 10;
    let harmonic_penalty = if residue_class == 0 {
        -3.0
    } else {
        let d = residue_class.min(10 - residue_class) as f64;
        d * 0.6
    };
    score += harmonic_penalty;

    // Dead-space cliff: post-residuals that can only host tiny items are bad.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Next item fits comfortably into post-residual: mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.25;
    }
    // Next item cannot use post-residual: penalize proportionally to waste.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Integer-division threshold on post_residual: quarter classes.
    let quarter = post_residual / (bin_capacity / 4);
    score -= quarter as f64 * 2.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin is tight enough.
    if bin_residual == bin_capacity {
        let tight_open = (mean_residual < item_size as f64 * 1.5) as i32 as f64;
        score += 10.0 - tight_open * 25.0;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Prefer filling bins below the mean residual (balancing via mean).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Mild penalty for many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder than proportionally (dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 5.0; // gap too small for the next item
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // when few bins are open, opening a new one is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New empty bin candidate: only attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        if mean_residual < 15.0 {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // Late in the stream, tighten up: avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (post_residual near 0).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Pairing bonus scaled by how well the chain continues.
            let leftover = (post_residual - next_item_size) as f64;
            let pair_quality = 1.0 - leftover / cap;
            score -= 20.0 * pair_quality;
        } else {
            // Penalize creating dead space that blocks the next item.
            let gap = (post_residual as f64) - (next_item_size as f64);
            score += 0.5 * gap.abs().min(50.0);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual deviates
    // from the mean in a way that suggests consolidation.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.1 * dev; // larger-than-average residual bins are slightly deprioritized

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity (better to keep it clean for large future items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64) / cap;
        score += 25.0 - 20.0 * big_item - 5.0 * progress;
        // If next item is also large, a fresh bin is more attractive.
        if next_item_size > 0 {
            score -= (next_item_size as f64) / cap * 10.0;
        }
    }

    // Mild preference for filling already-open bins as stream progresses.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a non-linear term.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 60.0;

    // Penalize leaving residual that is too small to be useful for typical items,
    // i.e. dead space in (0, 10). Post-residual below 10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily;
    // if the next item cannot fit in post-residual but would fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (1.0 - slack as f64 / bin_capacity as f64) * 35.0;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residuals
    // across open bins are tight / item is large and fits poorly everywhere.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let mut new_bin_score = 70.0 + tightness * 40.0;
        if large_item {
            new_bin_score -= 30.0;
        }
        if post_residual >= item_size {
            // Empty bin can host the item twice: somewhat more attractive.
            new_bin_score -= 10.0;
        }
        score = new_bin_score + post_residual as f64 * 0.5;
        return score;
    }

    // Prefer filling bins whose residual is close to the item size (global packing pressure).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Mild reward for consolidating when many bins are open (reduce fragmentation).
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Time horizon: early in the stream, be slightly conservative (favor new bins
    // less); late in the stream, squeeze everything into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Coupling with mean residual: if mean residual is large (lots of slack overall),
    // be pickier about which bin receives the item.
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let tight = (fit_ratio - 0.5) * (fit_ratio - 0.5); // penalize half-empty tails quadratically
    let tight4 = tight * tight;
    score += 40.0 * tight4 * (0.5 + progress) * cap;

    // Reward near-perfect fits with progress-scaled bonus
    let perfect = 1.0 - fit_ratio;
    score -= 25.0 * perfect * perfect * perfect * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item fits poorly in resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score += 0.15 * gap;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).sqrt() * 0.5;
    // Mean-residual coupling: prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: keep neutral baseline, slightly favored late when residuals are small
    if bin_residual == bin_capacity {
        score = pr - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that no small item (>=10... but
    // interface allows >=1) can fill is penalized via integer-division thresholds.
    // Class 0: post_residual == 0 -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes of post_residual mod 10 (classic bin-packing dead zones)
    let r = post_residual % 10;
    let dead_penalty = match r {
        0 => -40.0,          // clean class: residual likely reusable by round items
        1 | 2 => 25.0,       // awkward slivers
        3 | 4 | 5 | 6 | 7 => 10.0, // mid-class: may fit medium items
        _ => 18.0,           // 8,9: nearly-full, hard to reuse
    };
    score += dead_penalty;

    // Integer division thresholds: residual tiers
    if post_residual <= 10 {
        score += 30.0; // nearly unusable dead space
    } else if post_residual <= 25 {
        score += 5.0;
    } else if post_residual <= 50 {
        score -= 15.0; // sweet spot: half-bin room
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class match: next item lands exactly in a good residual class
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 120.0; // chain of perfect fits
            } else if gap <= 10 {
                score -= 40.0;
            } else if gap <= 30 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += 20.0; // next item won't reuse this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // prefer tighter bins among many candidates: post_residual already does this
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // and no open bin is tight. Penalize opening new bins mildly by default.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // new bin is good for very large items late in stream, or when mean residual is high
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 80.0 * (fill_frac - 0.6).max(0.0) + 30.0 * (mean_residual / bin_capacity as f64 - 0.5).max(0.0) + 10.0 * progress;
        score += 55.0 - new_bin_bonus; // net penalty unless conditions favor new bin
    }

    // Slight preference for keeping number of open bins from exploding early
    score += 0.5 * open_bins_count as f64;

    // Progress-scaled tie-breaker: tighten bins more aggressively later in stream
    score -= 10.0 * (step_index as f64 / total_items.max(1) as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty, scaled by how useless it is.
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 20 {
            // Marginal gap: only usable for tiny items; moderate penalty.
            score += (20 - post_residual) as f64 * 3.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0; // chains perfectly with next item
        } else {
            score -= 8.0; // at least still usable
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // blocks the known next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Mild penalty when this bin's residual is far below the mean (it is already
    // the tightest bin; better to drain looser bins first).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    }

    // New-bin candidate: make it moderately expensive, but cheaper late in the
    // stream when consolidation matters less than avoiding bad gaps.
    if bin_residual == bin_capacity {
        score += 30.0 - 15.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item chain
        }
        // Penalize leftover that next item cannot use and is small (dead space)
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 10.0;
    }

    // Favor bins that are already relatively full (small residual vs mean).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    }

    // Mild late-stream tightening: waste hurts more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

