pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: normalized post-residual (tight fit preferred)
    let mut score = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, squeeze residual harder.
    let coupling = pr / cap * (1.0 + 2.0 * progress * progress + 1.5 * progress);
    score += 0.8 * coupling;

    // Penalize residuals that are too small to ever be useful (dead space),
    // with a smooth quadratic ramp relative to capacity.
    let dead = (1.0 - pr / cap).max(0.0);
    score += 0.4 * dead * dead * (1.0 - dead);

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize otherwise (smoothly scaled by next item size).
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let nx = next_item_size as f64 / cap;
        score -= 0.6 * fits_next * nx;
        score += 0.3 * (1.0 - fits_next) * (pr / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 1.2 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap) * progress;

    // Slight preference for keeping residuals near multiples of typical item sizes:
    // smooth sinusoidal alignment bonus.
    score -= 0.1 * ((std::f64::consts::PI * pr / 20.0).cos()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in "nice" classes
    // (multiples of 10, or small dead zones) get adjusted priorities.
    let post_class = (post_residual / 10) % 10;
    match post_class {
        0 => { score -= 8.0; }              // perfectly full / clean class
        1 | 2 => { score += 6.0; }          // tiny dead space (1..=29): hard to reuse
        3 | 4 => { score -= 3.0; }          // medium reusable space
        5 => { score -= 5.0; }              // residual ~50: half-capacity class, very reusable
        _ => { score += 1.0; }              // large residual: fine but not special
    }

    // Penalize dead space relative to the smallest plausible item (1..=100 unknown dist,
    // assume min item ~10): residual below 10 is pure waste.
    if post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Integer-division threshold: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chain two items: strong reward
            // Harmonic coupling: bonus if next item leaves another clean class
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 { score -= 4.0; }
        } else {
            score += 5.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // fit is poor (large post_residual waste) or many bins already open.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // default: new bin is moderately penalized so real bins win
        score = 40.0 + waste * 0.2
            - 10.0 * progress
            - 2.0 * (open_bins_count as f64).ln().max(0.0);
        // if this bin is the ONLY fitting option and fit is bad, allow opening
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Mild preference for tighter-than-average bins.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        // gap too small for any realistic item -> dead space
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Prefer bins whose residual was large (good utilization of big gaps).
    score -= 0.15 * bin_residual as f64;

    // Open-bin pressure: discourage spreading when many bins are open,
    // unless this is the last chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0; // last chance: strongly prefer using this bin
    }

    // New empty bin candidate: only attractive if item is large relative
    // to mean residual or no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 8.0;
        let mean_fit = mean_residual >= item_size as f64;
        if mean_fit {
            score += pressure + 20.0; // an open bin could take it; deprioritize new bin
        } else {
            score -= 15.0; // no open bin fits well -> open new bin
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score += 10.0; // item + next won't share a bin anyway
        }
    }

    // Lookahead: if the post residual exactly fits the next item, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 5.0;
    }

    // Mild stream-progression tightening: later in stream, be more conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item exactly matches post_residual,
    // this placement chains perfectly -> huge reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterward: reward closeness
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would NOT fit in the leftover: penalize dead space
            score += 50.0 + diff * 0.5;
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // leaving less than average residual is good (tight packing).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize new-bin candidate (bin_residual == bin_capacity) unless the item
    // is very large relative to residual or no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if item_size > 50 {
            score -= 100.0 * tightness; // big items: fresh bin is fine
        } else {
            score += 120.0; // small items should try existing bins first
        }
    }

    // Small bonus for consolidating bins early in the stream (keep bin count low).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual), with a sweet spot near zero.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio * (bin_capacity as f64);

    // Reward near-perfect packing strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Penalize creating dead space that cannot fit typical future items:
    // post_residual just below the next item size is wasted.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0 * (next_item_size - post_residual) as f64;
        }
        // Bonus if post_residual can still fit the lookahead item.
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when the item fits poorly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a fresh bin, decaying slightly as stream progresses.
        score += 30.0 - 10.0 * progress;
        // If many bins are open and mean residual is high, discourage new bins.
        score += 0.05 * open_bins_count as f64;
        score += 0.1 * (mean_residual - 20.0).max(0.0);
        // A fresh bin is better when the item is large and leaves awkward remainder.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // Slight preference for fuller bins (smaller residual) among open bins.
        score += 0.02 * bin_residual as f64;
        // Prefer using bins with residual far from mean (consolidate fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * dev;
    }

    // Early stream: be conservative, keep bins balanced; late stream: greedy tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = pr + 60.0 * pr_norm * pr_norm;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tighten up more aggressively on waste.
    let coupling = pr_norm * (0.5 + 2.0 * progress) * (1.0 - pr_norm);
    score += 40.0 * coupling * (progress - 0.5).abs() * 2.0;

    // Penalize bins whose residual deviates from mean (fragmentation avoidance),
    // scaled smoothly by progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * 30.0 * (0.25 + 0.75 * progress);

    // Reward near-perfect fits with a smooth Gaussian-like bump.
    let fit_quality = (-8.0 * pr_norm * pr_norm).exp();
    score -= 25.0 * fit_quality;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let next_fit = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 15.0 * next_fit * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Quarters / eighths harmonic classes: leftover near multiples of small item sizes (10..20)
    // is more reusable. Reward post_residual that is divisible-friendly.
    let pr_u = post_residual;
    let mod10 = (pr_u % 10) as f64;
    let mod20 = (pr_u % 20) as f64;
    score += (mod10 / 10.0) * 4.0;              // slight penalty for awkward remainder mod 10
    if pr_u % 20 == 0 { score -= 3.0; }          // harmonic class: exact multiple of 20
    if pr_u % 10 == 0 { score -= 1.5; }

    // Dead space penalty: leftover too small for the smallest plausible item (1..100, min 1)
    // but too small to be broadly useful (< 20).
    if pr_u > 0 && pr_u < 20 {
        score += 12.0 * (1.0 - pr_u as f64 / 20.0);
    }
    if pr_u == 0 { score -= 8.0; }               // perfect fill is excellent

    // Exact-fit harmonic classes via integer division thresholds on item vs residual.
    let q = bin_residual / item_size.max(1);     // how many copies could fit
    if q >= 2 { score -= 2.0 * (q.min(4) as f64); }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if next item is huge and current fit leaves tiny scraps, new bin is fine.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap && pr_u < 15 {
            score -= 20.0;
        }
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr_u {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size < pr_u {
        score -= 3.0 * (1.0 - ((pr_u - next_item_size) as f64) / cap);
    }

    // Progress-aware tightening: late in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - frac * cap).abs() * 0.05;
    score += 0.02 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (below a "dead zone" threshold) are heavily penalized.
    let dead_zone = 9.0; // nothing in 1..10 range is likely to fill a tiny gap
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Reward filling a bin that is more than half consumed.
    if bin_residual <= bin_capacity / 2 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let left = post_residual - next_item_size;
            if left < dead_zone as u32 && left > 0 {
                score += 6.0; // would create dead space for next item
            } else {
                score -= 8.0;
            }
        }
    }

    // Mean-residual coupling: penalize bins far below mean residual
    // (they are the "worst fit" candidates); favor above-mean fits mildly.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    // New-bin candidate: make empty-bin score moderate; only chosen when
    // no open bin offers a decent fit (its raw post_residual = capacity
    // keeps it naturally high, plus a small offset).
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically (small post_residual is good).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: strongly reward if the next item fits exactly/well into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect 2-chain match: subtract a big bonus scaled by tightness.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward for exact match (chain closes bin).
            if gap < 1.0 {
                score -= 40.0;
            }
        } else if next_item_size <= post_residual + mean_residual.max(0.0) as u32 {
            // Next item could still fit after future rebalancing: mild reward.
            score -= 5.0;
        } else {
            // Next item will not fit: penalize leaving awkward leftover space.
            score += 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Slight preference for keeping fewer open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * progress;

    // New empty bin candidate: only attractive when current fit is bad
    // (large post_residual waste) — make empty bin moderately unattractive by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is huge relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post_residual lightly (wasted space), but reward tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: small post_residual that no future item (min size 1... but typical >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; slight penalty proportional to overflow mismatch
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when open bins are crowded (mean residual low) or few bins fit.
        let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 - 45.0 * pressure;
        // Early in stream, opening bins is cheap; later, prefer reusing.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins already fit the item, discourage opening a new one.
        score += 8.0 * fitting_bins_count as f64;
    }

    // Global fragmentation signal: if mean residual is high, prefer filling existing bins harder.
    if mean_residual > 0.0 && !is_new_bin {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 10.0 * frag * tightness;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Quadratic waste penalty: small leftovers are fine, big leftovers are dead space.
    score += 0.9 * (post / cap) * (post / cap) * cap;

    // Smooth coupling of waste with stream progress: as the stream advances,
    // become increasingly intolerant of large residuals (consolidate early, tighten late).
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Lookahead: penalize residuals that cannot host the next item (creates stranded gaps),
    // reward residuals that can exactly or comfortably host it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 4.0 * (1.0 - slack * slack); // next item fits here: strong reward
        } else {
            let gap = (nxt - post) / cap;
            score += 6.0 * gap * gap * cap; // dead space relative to lookahead
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty when this bin is much tighter than the fleet average
    // (prefer spreading fill evenly, keeps future options open early on).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= (1.0 - progress) * 2.0 * dev;

    // New-bin candidate: make it slightly unattractive unless residual waste elsewhere is severe.
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is best
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class of post_residual: dead-space bands
    // Residuals that are hard to fill later (small odd/prime-ish leftovers) get penalized
    let pr = post_residual;
    if pr > 0 {
        // penalize residuals below typical minimum item size
        if pr < 10 {
            score += 60.0 + (10 - pr) as f64 * 4.0;
        }
        // modulo structure: residuals that divide capacity into nice chunks are reusable
        let m = pr % 25;
        if m == 0 {
            score -= 40.0; // 25/50/75 leftovers align with mid-size items
        } else if m == 10 {
            score -= 20.0;
        } else if m % 2 == 1 && pr < 40 {
            score += 15.0; // small odd residuals are awkward
        }
        // integer division thresholds
        if pr / 20 == 0 {
            score += 25.0; // pr in 1..19: mostly dead space
        } else if pr / 20 >= 3 {
            score -= 10.0; // large leftover still useful
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; mildly penalize tight leftovers
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.7 {
            score -= 80.0; // fresh bin for a big item is fine
        } else {
            score += 120.0 + (0.7 - fill_frac) * 200.0; // discourage wasting fresh bins
        }
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 30.0;
    }

    // Prefer tighter existing bins (low residual relative to mean)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Congestion: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable "dead" gaps: residuals below the minimum plausible item size
    // create pure waste. Escalate the penalty as the gap shrinks toward zero.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits (residual <= 2) strongly.
    if post_residual <= 2 {
        score -= 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer it over opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item can exactly fill the post-residual,
    // this placement is excellent; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (post_residual.min(next_item_size) as f64) * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already tight; encourage new bins when open bins are mostly full.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);
    score += pressure * (2.0 + progress);

    // New-bin candidate baseline: slightly above well-fitting open bins,
    // but below bins that would leave large dead space.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next_item_size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        // Exact match bonus: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits, penalize leftover after that hypothetical placement.
            let after_next = post - nxt;
            score -= 25.0 - 0.35 * after_next;
        } else {
            // Next item won't fit here; penalize proportionally to how far off.
            score += 0.4 * (nxt - post);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual against mean residual: creating small residuals wastes space.
    if (post_residual as f64) < mean_residual * 0.35 {
        score += 15.0; // dead-space penalty
    } else if (post_residual as f64) > mean_residual * 1.6 {
        score -= 8.0; // keeps bin flexible relative to average
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && (next_item_size as f64) > 0.85 * bin_capacity as f64 {
            score -= 55.0; // reserve fresh bins for very large upcoming items
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the next item (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time-horizon scaling: early in the stream, be conservative (favor filling
    // existing bins); later, allow opening new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // New-bin candidate logic: only attractive when residuals across open bins
    // are fragmented (high mean residual spread) or many bins already open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        let threshold = 28.0 + pressure + 0.5 * fragmentation;
        // Penalize opening a new bin unless current fit is poor.
        let fit_penalty = (bin_residual - item_size) as f64;
        score += threshold - 0.6 * fit_penalty;
        // Late in stream, opening a bin is cheaper.
        score -= progress * 10.0;
    }

    // Mild penalty for bins whose residual deviates far from the mean
    // (keeps residual distribution balanced for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight preference for fuller bins.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor small post_residual via non-linear coupling.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score -= (1.0 - pr_norm).powi(2) * cap * 0.8;

    // Penalize dead space that is too small to be useful later, scaled by progress.
    let dead = if pr > 0 && pr < item_size { 1.0 } else { 0.0 };
    score += dead * (pr * 0.5) * (0.5 + progress);

    // Lookahead coupling: if next item fits in post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= (pr - n) * 0.3 + 5.0 * (1.0 - progress);
        } else {
            score += (n - pr) * 0.2 * (0.5 + progress);
        }
    }

    // Last chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: make it attractive only when existing bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).powi(2);
        score += 15.0 * (1.0 - frag) - 10.0 * progress;
    }

    // Mild penalty for using a bin whose residual deviates strongly from the mean (balance).
    score += ((bin_residual as f64 - mean_residual).abs() / cap) * 4.0;

    // Non-linear stream-progress coupling on residual: later in stream, prefer fuller bins.
    score += pr_norm * pr_norm * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // size classes (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        let mut harmony_bonus = 0.0;
        if pr % 10 == 0 { harmony_bonus += 8.0; }
        if pr % 20 == 0 { harmony_bonus += 6.0; }
        if pr % 25 == 0 { harmony_bonus += 6.0; }
        if pr % 50 == 0 { harmony_bonus += 10.0; }
        score -= harmony_bonus;

        // Penalize tiny unusable dead space (harshly in the 1..10 band)
        if pr < 10 {
            score += (10 - pr) as f64 * 4.0;
        } else if pr < 20 {
            score += (20 - pr) as f64 * 1.5;
        }

        // Lookahead coupling: does next_item_size fit harmonically into post_residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                // reward exact harmonic match, reward divisibility
                if pr % next_item_size == 0 {
                    score -= 15.0;
                } else {
                    let slack = pr - next_item_size;
                    if slack < 10 { score += 3.0; } // leaves near-dead space
                    score -= 5.0; // at least next item fits
                }
            } else {
                score += 4.0; // next item won't fit here anyway
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: prefer new empty bin only when open bins
    // would create badly fragmented space.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.5 - 20.0 * progress;
        if item_size % 10 == 0 { score -= 5.0; } // round sizes pack well fresh
    }

    // Mild preference for fuller bins (low residual before placement)
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight tie-break toward bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0; // creates a gap too small for next item
        }
