    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open
        score += 25.0 + 2.0 * pressure;
    } else {
        score -= pressure.min(20.0);
    }

    // Prefer bins tighter than the mean residual (filling fuller bins first)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact-tight fit reward (small post residual is good).
    score -= 20.0 / (1.0 + post_residual as f64);

    // 2-step lookahead: if the next item exactly fills the post residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item also fits here: mild reward proportional to closeness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + gap);
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
