    // Penalize bins far from the mean residual (avoid fragmenting outliers),
    // unless it's a last-chance bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // or many bins are already open (spread load to keep chains viable).
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size > 60 || open_bins_count > 6 {
            score -= 10.0;
        }
    }

    // Late-stream tightening: prefer compact packing as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
