    // Crowd penalty: many open bins -> prefer consolidating into fuller bins
    score += 0.15 * (open_bins_count as f64 - 1.0).max(0.0) * norm_pr;

    // Lookahead: reward if next item fits into post_residual (smooth coupling)
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let next_norm = next_item_size as f64 / cap;
        score -= 12.0 * fits_next * next_norm * (1.0 - progress * 0.5);
        // penalize post_residual that is just barely too small for next item (dead space)
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 8.0 * gap * gap * 10.0;
    }

    // Mean residual context: if this bin's residual deviates from mean, mild penalty
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad,
    // but relax penalty as stream progresses
    if bin_residual == bin_capacity {
