}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class A: post_residual is a multiple of 10 or >= 50 (still broadly usable)
    // Class B: small awkward leftover (1..10) -> dead space, penalize
    // Class C: exact fit -> big reward
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 9 {
        // dead space: worse the smaller it is relative to typical item (>=10)
        score += (10 - pr) as f64 * 3.0;
        // extra penalty if no future item can use it
        if next_item_size > pr {
            score += 15.0;
        }
    } else {
        // usable leftover: reward proportionally to capacity fraction
        let frac = pr as f64 / cap;
        score -= frac * 20.0;
        // integer-division threshold: leftover can hold at least one more item
        if next_item_size > 0 && pr >= next_item_size {
            score -= 12.0;
            // harmonic bonus: leftover divisible into chunks of next item size
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        }
        // modulo-10 harmonic classes: multiples of 10 leftovers pair well
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 30.0 + open_bins_count as f64 * 0.5;
        // but if mean residual is too small to fit typical items, opening is fine
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
        // lookahead: if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // mild preference for tighter bins (best-fit flavor) already via post_residual
        // penalize bins much looser than the mean (fragmenting behavior)
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 5.0;
        }
    }

    // Stream progression: late in stream, avoid opening new bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
