        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins early.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (open_bins_count as f64) * 0.6 * (1.0 - 0.5 * progress);

    // Prefer bins whose residual is close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward if next item can fit the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: neutral baseline, penalize slightly so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong base penalty on wasted residual, superlinear to kill dead space.
    score += 0.35 * (post_residual as f64).powf(1.25);

    // 2-step lookahead: reward exact or near-exact match of next item into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            // Next item fits perfectly: big reward.
            let gap = (post_residual as f64 - nxt).abs();
            score -= 18.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit: penalize tight leftovers that become dead space.
            score += 6.0 * (post_residual as f64 / cap);
        }
    }

    // Match against mean residual: prefer bins whose post residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild preference to fill nearly-full bins (small post residual) as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_residual as f64) * 0.05;

    // Penalize opening new bins when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively for small leftovers.
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 12.0;
    } else if post_residual < 35 {
        score -= 4.0;
    }

    // Penalize dead space: residual too small for typical future items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    }
    // If next item would NOT fit after this placement but fits elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_residual {
        score += 6.0;
    }

    // New-bin candidate logic: opening a new bin is attractive when existing residuals
    // are fragmented (high mean residual spread) or late in the stream with many bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early (consolidate), reward later when item is large.
        score += 20.0 - 30.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If many bins can fit the item, opening new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // If only one bin fits and it's tight, new bin becomes reasonable.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is close to item_size (good fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Coupling with global mean residual: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferating bins when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let p = progress;
    let coupling = pr_norm * pr_norm * (1.0 - p) + pr_norm * p * p;
    score += 30.0 * coupling;

    // Reward tight fits with smooth term
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit * fit * (1.0 + p);

    // Penalize dead space that next item cannot use (smooth kernel)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let k = gap / bin_capacity as f64;
            score += 20.0 * k * k * (1.0 - k);
        } else {
            score -= 10.0 * (-gap / bin_capacity as f64);
        }
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - p);
    }

    // Mild penalty for opening new bin relative to open bins count
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (1.0 - p) - 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mean residual alignment term
    score += 3.0 * (pr - mean_residual) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of common
    // item sizes are more likely reusable, reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { harmony += 6.0; }
        }
        // small dead space classes (1..=9) are worst
        if pr < 10 { harmony -= 25.0 * (10 - pr) as f64; }
        score -= harmony;
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Integer-division threshold on post_residual: chunks of capacity
    let chunks = (pr / 25) as f64;
    score -= 4.0 * chunks;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // harmonic class of (pr - next): does the pair leave a clean residual?
            let pair_res = pr - next_item_size;
            if pair_res % 10 == 0 { score -= 12.0; }
            if pair_res < 10 { score += 15.0; }
            score += (pair_res % 10) as f64; // modulo penalty on leftover class
        } else {
            // next item won't fit here; slight penalty for tight bins blocking lookahead
            score += 5.0;
        }
    } else {
        // last item: just minimize waste
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual < 10 { score += 10.0; } // unless it creates dead space
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to mean residual space or few bins fit the item.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / cap) - (mean_residual / cap);
        score = cap * 0.55 - 30.0 * pressure;
        if fitting_bins_count == 0 { score -= 100.0; }
        if next_item_size > 0 && next_item_size >= item_size && pressure > 0.1 {
            score -= 8.0; // pairing large items together in fresh bins
        }
    }

    // Late-stream consolidation: prefer tighter fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving space usable by the next item (lookahead fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: mild reward for reusing existing bins vs. new bin.
    if bin_residual != bin_capacity {
        score -= 2.0 + open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: penalize slightly unless current bins are crowded.
        score += 5.0 - (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
    }

    // Late-stream tightening: prefer compact packing as stream progresses.
    score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize unusable dead space.
    // Dead space: post_residual too small for the smallest plausible next item (1..100 range).
    if post_residual > 0 {
        // Fragmentation penalty: residual that likely can't be used.
        let frag_threshold = 10.0f64.min(post_residual as f64);
        score += (bin_capacity as f64 * 0.5 - post_residual as f64).abs() * 0.05;
        let _ = frag_threshold;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: next item chains into this bin -> strong reward.
            score -= 40.0 + 0.5 * (next_item_size as f64);
            // Extra reward for a near-perfect chain (post_residual barely fits next item).
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the overshoot.
            let overshoot = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 30.0 * overshoot;
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better consolidation targets.
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 25.0 * dev;

    // Last-chance logic: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make the empty bin attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with good lookahead wins beat it,
        // but low enough to win when all open bins have bad fits.
        score += 15.0;
        // Late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If next item is large, a fresh bin is actually valuable (room for both).
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Slight preference to fill earlier bins first (stabilizes open-bin count).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization), with a squashed ratio.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating small unusable dead space (< 10) heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }
    if post_residual == 0 {
        score -= 8.0; // perfect fill
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item cannot fit the leftover, penalize dead space creation.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0; // chain fill opportunity
            } else {
                score -= 2.0;
            }
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // the item is large or the stream is early and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items early on; penalize for small items.
        score = 25.0 - 20.0 * item_frac + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // forced new bin
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 5.0; // next item may need fresh space anyway
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
        // Slight load balancing across many open bins.
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, larger post_residual is more tolerable (future items can fill it);
    // late in the stream, dead space is nearly permanent, so penalize quadratically.
    let dead_weight = 1.0 + 2.0 * progress * progress;
    score += dead_weight * (pr / cap) * (pr / cap) * cap * 0.5;

    // Reward tight fits (small post_residual) with a saturating bonus.
    let tight = (1.0 - pr / cap).clamp(0.0, 1.0);
    score -= 10.0 * tight * tight;

    // Penalize leaving a residual that is too small for typical future items,
    // smoothly scaled by mean residual context.
    let small_gap = (pr / cap).clamp(0.0, 1.0);
    score += 5.0 * small_gap * (1.0 - small_gap) * (mean_residual / cap + 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly discourage opening a new bin when the stream is late
    // and open bins can still fit the item; encourage it early if post_residual is large.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 8.0 + 12.0 * progress - 0.02 * open_bins_count as f64;
        score += new_bin_penalty;
    } else {
        // Slight preference for bins whose residual is closest to the item (best fit flavor)
        score -= 3.0 * (1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs());
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 4.0 * (next_item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small" residue class (mod 10) are near-perfect fits; reward them.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0; // leftover is a multiple of 10 -> highly reusable
    } else if class <= 2 {
        score -= 3.0; // tiny dead space, acceptable
    } else if class >= 8 {
        score += 2.0; // awkward leftover just under a decade boundary
    }

    // Integer-division thresholds: leftover big enough for another
    // medium/large item is valuable.
    if post_residual >= 50 {
        score -= 8.0;
    } else if post_residual >= 30 {
        score -= 4.0;
    } else if post_residual >= 20 {
        score -= 2.0;
    } else if post_residual > 0 {
        score += (10 - post_residual) as f64 * 0.5; // dead space penalty
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Harmonic residue match between next item and leftover
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item won't fit here; penalize slightly more for
            // large wasted residuals
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the
    // item is large relative to capacity and few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        let new_bin_cost = 100.0 - 40.0 * fill_fraction
            - 15.0 * progress
            - 2.0 * open_bins_count as f64;
        score += new_bin_cost.max(5.0);
    }

    // Tie-break: prefer tighter bins (small residual before placement).
    score += bin_residual as f64 * 0.02;
    score -= mean_residual * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 80.0;
    }

    // Penalize gaps that no plausible future item can use (sizes 1..100).
    if post_residual > 0 && post_residual < 100 {
        // small gaps below min item size are dead
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover < 10 {
            score -= 40.0; // chain of near-perfect fits
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0; // next item cannot use this gap
    }

    // Open-bin pressure: discourage spreading across many bins when a decent fit exists.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but less so early in the stream or when open bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = mean_residual / bin_capacity as f64;
        score += 20.0 - 15.0 * avg_fill - 10.0 * progress;
    }

    // Prefer bins tighter than average (below-mean residual = fuller bin).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward bins whose leftover can host the next item (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + (next_item_size as f64) * 0.5;
    }

    // Penalize near-exact fits that leave a dead sliver (unusable residual).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(10) {
        score += 25.0;
    }

    // Perfect closure bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Compare against mean residual: bins below mean are "tight"; prefer
    // placing into them to consolidate space, penalize opening space in fat bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or many bins are open (spread management).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64) / (bin_capacity as f64) > 0.6;
        let mut penalty = 45.0;
        if large_item { penalty -= 30.0; }
        if open_bins_count > 8 { penalty -= 10.0 * progress; }
        // If the next item also fits a fresh bin chain, mild discount.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Slight preference for tighter fits overall (waste minimization).
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 8.0 * (dead_threshold - post_residual as f64);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 2.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless it's a
    // genuinely better home (e.g., very large item, few fitting bins).
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 0.5 * open_bins_count as f64;
        let relief = if fitting_bins_count <= 1 {
            40.0
        } else if item_size >= 60 {
            18.0
        } else {
            0.0
        };
        score += base_penalty - relief;
    }

    // Global state: when mean residual is high, prefer consolidating into
    // fuller bins (score already lower for small post_residual, add coupling).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * (mean_residual - post_residual as f64) * (0.5 + 0.5 * progress);

    // Late in the stream, be extra frugal with open bins.
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) + x * x * x * t;
    score += 40.0 * poly;

    // Reward tight fits more as stream progresses
    let tightness = 1.0 - x;
    score -= 15.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space relative to mean residual (smooth coupling)
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x * x);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let compat = 1.0 - ((x - nx) * (x - nx));
        score -= 10.0 * compat * compat * x;
        // Penalize if post residual is just barely below next item
        if x < nx {
            score += 12.0 * (nx - x) * (nx - x) * 10.0;
        }
    }

    // Mild preference for keeping fewer open bins early
    score += 0.5 * open_bins_count as f64 * t * x;

    // New-bin candidate: penalize slightly so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - t) + 60.0 * (1.0 - (pr / cap).powi(2)) * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common small item sizes (10, 20, 25, 50)
    // are more likely to be filled later -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 3.0; }
        // Dead-space penalty: tiny unusable leftovers (1..10) are nearly wasted.
        if pr < 10 { score += 12.0; }
        // Mid-range awkward classes: 11..19 leftover rarely fits small items well.
        if pr >= 11 && pr <= 19 { score += 4.0; }
    } else {
        // Perfect fit is the best outcome.
        score -= 30.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the post
    // residual, this is a harmonic chain -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
        if post_residual == next_item_size { score -= 8.0; }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this leftover: penalize proportional waste.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with number of open bins (avoid bin proliferation).
        score += 8.0 + open_bins_count as f64 * 0.5;
        // But if the current item is large and would leave a tiny residual in any
        // existing bin, a fresh bin is fine; also early stream -> cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 4.0;
        if item_size > bin_capacity / 2 { score -= 5.0; }
    }

    // Tightness bonus: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 10.0;

    // Mean-residual coupling: if this bin is far below mean residual, it is a
    // good "garbage collector" bin; reward slightly.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 { score -= dev * 0.05; } else { score += (-dev) * 0.03; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 10)
    // are wasted; penalize them heavily.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderate penalty for "awkward" residuals (11..=20) that few items can use.
    if post_residual >= 11 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (small but nonzero post_residual is good if >= 10).
    if post_residual >= 10 && post_residual <= 25 {
        score -= 15.0 - (post_residual as f64 - 10.0);
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, opening a new bin is cheap.
    if bin_residual == bin_capacity {
        score += 8.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 3.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would leave this bin stranded, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Align with mean residual: prefer bins whose post-residual is close to the mean,
    // keeping residuals balanced for future items.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Early stream: slightly prefer consolidation into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain: bin becomes exactly full
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize remaining slack after hypothetical next placement.
            score += 0.35 * slack;
            // Bonus if next item leaves a small, still-usable remainder.
            if slack <= 10.0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Keeping residuals balanced is good, but extreme small residuals are dead space.
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Penalize unusable dead space: residual below the smallest possible item.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current item fits poorly anywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if item leaves a large residual (small item into empty bin) and
        // lookahead chains well, allow it; if item is huge, opening a fresh bin
        // preserves flexibility elsewhere.
        if item_size >= 50 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            // chain unlikely; discourage further
            score += 10.0;
        }
        // Early in stream, opening bins is cheaper (more items to come to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    score
}
